window.CATALOGO_FVS_CRITERIOS={"[\"Esquadrias\",\"Colocação Kit Porta Pronta :: Condição para Início do Serviço\"]":"INSTRUÇÃO:\nChecar planta de arquitetura para verificar o tamanho do vão; finalização do revestimento; e instalação de soleiras e baguetes.","[\"Esquadrias\",\"Colocação Kit Porta Pronta :: Posicionamento do Batente em Relação à Abertura da Porta\"]":"INSTRUÇÃO:\nVerificar lado de abertura da porta conforme projeto de arquitetura.","[\"Esquadrias\",\"Colocação Kit Porta Pronta :: Verificação das Dobradiças\"]":"INSTRUÇÃO:\nVerificar se o kit porta pronta está com todas as dobradiças e parafusos necessários.","[\"Esquadrias\",\"Colocação Kit Porta Pronta :: Prumo do Kit Porta Pronta\"]":"INSTRUÇÃO:\nVerificar, após o posicionamento do kit, o prumo dos batentes, com um prumo de face.\n\nTOLERÂNCIA:\n3 mm","[\"Esquadrias\",\"Colocação Kit Porta Pronta :: Nível / Alinhamento e Esquadro\"]":"INSTRUÇÃO:\nVerificar o nivelamento da peça com nível de mangueira ou nível a laser, e o alinhamento/esquadro do kit porta pronta em relação à alvenaria com a régua.\n\nTOLERÂNCIA:\n3 mm","[\"Esquadrias\",\"Colocação Kit Porta Pronta :: Fixação\"]":"INSTRUÇÃO:\nFixação do kit porta pronta com espuma de poliuretano (espuma expansiva).\n\nTOLERÂNCIA:\n3 pontos em cada batente de porta interna e todo o perímetro em portas de entrada","[\"Esquadrias\",\"Colocação Kit Porta Pronta :: Colocação das Fechaduras\"]":"INSTRUÇÃO:\nVerificar o funcionamento de maçanetas e maçaneta digital (onde houver) e máquinas das portas (verificar se as chaves giram naturalmente na máquina).","[\"Esquadrias\",\"Colocação Kit Porta Pronta :: Acabamento, Funcionamento das Portas e Instalação das Guarnições\"]":"INSTRUÇÃO:\nVerificar a abertura e fechamento das portas e o acabamento da guarnição instalada.","[\"Alvenaria\",\"Marcação Alvenaria :: Condição para Início dos Serviços\"]":"INSTRUÇÃO:\nA opção de planta do apto deverá estar identificada na entrada do apto. Verificar visualmente a limpeza geral, a transferência dos eixos, o chapisco nos locais necessários e se o nível de referência está definido.","[\"Alvenaria\",\"Marcação Alvenaria :: Posicionamento da Fiada de Marcação\"]":"INSTRUÇÃO:\nAtravés de trena metálica, verificar a posição em relação aos eixos, de acordo com o projeto (incluindo a análise dos vãos).\n\nTOLERÂNCIA:\n± 3 mm","[\"Alvenaria\",\"Marcação Alvenaria :: Esquadro da Fiada de Marcação\"]":"INSTRUÇÃO:\nAtravés de esquadro metálico de 60 cm x 80 cm.\n\nTOLERÂNCIA:\n± 3 mm (na ponta de 60 cm)","[\"Alvenaria\",\"Marcação Alvenaria :: Alinhamento da Fiada de Marcação\"]":"INSTRUÇÃO:\nAtravés da linha e da possibilidade de adequação pela estrutura.\n\nTOLERÂNCIA:\nAté 3 mm de diferença em relação à linha esticada; 10 mm para caso de estrutura","[\"Alvenaria\",\"Marcação Alvenaria :: Tubulação de Dreno\"]":"INSTRUÇÃO:\nA tubulação dos drenos deverá estar posicionada no centro da marcação, a uma altura de pelo menos 1,0 metro. Método/procedimento: visual.","[\"Alvenaria\",\"Marcação Alvenaria :: Conduites Elétricos\"]":"INSTRUÇÃO:\nTodos os conduítes deverão estar posicionados conforme projeto de vedação. Método/procedimento: visual.","[\"Alvenaria\",\"Marcação Alvenaria :: Nivelamento da Fiada de Marcação\"]":"INSTRUÇÃO:\nAtravés de nível alemão, régua de bolha ou nível de mangueira.\n\nTOLERÂNCIA:\n3 mm em relação ao nível de referência ou bolha entre linhas (régua de bolha)","[\"Alvenaria\",\"Elevação Alvenaria :: Condição para Início dos Serviços\"]":"INSTRUÇÃO:\nA marcação deverá estar conferida e liberada.","[\"Alvenaria\",\"Elevação Alvenaria :: Dreno do Ar Condicionado\"]":"INSTRUÇÃO:\nÉ necessário que o dreno do ar condicionado fique com a altura conforme projeto. Método/procedimento: visual.","[\"Alvenaria\",\"Elevação Alvenaria :: Tela Galvanizada\"]":"INSTRUÇÃO:\nPosicionamento das telas na estrutura a cada 40 cm (duas fiadas), antes do início da elevação.\n\nTOLERÂNCIA:\n1 cm","[\"Alvenaria\",\"Elevação Alvenaria :: Preenchimento com Argamassa dos Blocos da Marcação Shaft\"]":"INSTRUÇÃO:\nVerificar visualmente se o preenchimento foi realizado.","[\"Alvenaria\",\"Elevação Alvenaria :: Prumo da Alvenaria\"]":"INSTRUÇÃO:\nAtravés de régua metálica de 1,80 m com nível de bolha acoplado.\n\nTOLERÂNCIA:\nBolha entre linhas","[\"Alvenaria\",\"Elevação Alvenaria :: Planesa da Alvenaria\"]":"INSTRUÇÃO:\nAtravés de trena metálica e régua metálica de 1,80 m com nível e bolha acoplado.\n\nTOLERÂNCIA:\n± 4 mm","[\"Alvenaria\",\"Elevação Alvenaria :: Prumo de Vãos de Portas e Dimensões dos Vãos das Janelas e Portas\"]":"INSTRUÇÃO:\nAtravés de régua metálica de 1,80 m com nível de bolha acoplado. Verificar as dimensões dos vãos das janelas e portas com auxílio de trena e régua.\n\nTOLERÂNCIA:\nBolha entre linhas","[\"Alvenaria\",\"Elevação Alvenaria :: Aspecto Geral da Alvenaria\"]":"INSTRUÇÃO:\nVisualmente, verificando rebarbas, nivelamento, uniformidade e preenchimento das juntas ou blocos quebrados.","[\"Alvenaria\",\"Elevação Alvenaria :: Espessura do Vão para Encunhamento\"]":"INSTRUÇÃO:\nVerificar visualmente a espessura de vão de encunhamento, para posterior preenchimento na FVS 002C.\n\nTOLERÂNCIA:\n1,0 cm a 3,5 cm","[\"Alvenaria\",\"Encunhamento :: Condições para Início de Serviço\"]":"INSTRUÇÃO:\nA fixação deve ser realizada nas lajes superiores para as inferiores. Recomenda-se o uso de bisnaga para encunhamento, seguindo o fluxo conforme pés de alvenaria.","[\"Alvenaria\",\"Encunhamento :: Encunhamento\"]":"INSTRUÇÃO:\nApós a conclusão da alvenaria, a argamassa deve cobrir a espessura da parede do bloco (2 cordões de massa de cada lado da parede).\n\nTOLERÂNCIA:\n1,5 cm a 3,5 cm","[\"Estrutura\",\"Blocos, Vigas e Cortinas de Fundação :: Condição de Início de Serviço\"]":"INSTRUÇÃO:\nChecar a cota de arrasamento, excentricidade da estaca/tubulão e liberação do consultor no projeto de fundação.","[\"Estrutura\",\"Blocos, Vigas e Cortinas de Fundação :: Verificar as Medidas, Níveis e Prumos dos Blocos\"]":"INSTRUÇÃO:\nAtravés de trena metálica conferir as dimensões das caixas (blocos). Verificar também o nível e o prumo.\n\nTOLERÂNCIA:\nDimensões ± 10 mm. Nível ± 10 mm. Prumo ± 3 mm.","[\"Estrutura\",\"Blocos, Vigas e Cortinas de Fundação :: Verificar as Medidas, Níveis e Prumos das Vigas de Fundação\"]":"INSTRUÇÃO:\nAtravés de trena metálica conferir as dimensões das vigas. Verificar também o nível e o prumo.\n\nTOLERÂNCIA:\nDimensões ± 10 mm. Nível ± 10 mm. Prumo ± 3 mm.","[\"Estrutura\",\"Blocos, Vigas e Cortinas de Fundação :: Locação de Forma\"]":"INSTRUÇÃO:\nCom o auxílio de trena metálica e prumo de centro, verificar se a forma está na locação correta.\n\nTOLERÂNCIA:\nDimensões ± 3 mm","[\"Estrutura\",\"Blocos, Vigas e Cortinas de Fundação :: Travamento da Forma\"]":"INSTRUÇÃO:\nChecar visualmente o travamento final e o encaixe das formas.","[\"Estrutura\",\"Blocos, Vigas e Cortinas de Fundação :: Armação\"]":"INSTRUÇÃO:\nChecar se a amarração está firme, se o cobrimento está conforme projeto, verificar a quantidade e a bitola das barras.","[\"Estrutura\",\"Blocos, Vigas e Cortinas de Fundação :: Posição das Peças\"]":"INSTRUÇÃO:\nChecar a posição do bloco em relação ao pilar e a posição correta das vigas.","[\"Estrutura\",\"Blocos, Vigas e Cortinas de Fundação :: Geral\"]":"INSTRUÇÃO:\nChecar o gastalho dos pilares deixando os arranques, marcar a posição das vigas deixando os arranques e checar também com o projeto de instalações elétricas a posição do ferro para o para-raio. Conferir com o auxílio de trena metálica.\n\nTOLERÂNCIA:\n± 3 mm","[\"Estrutura\",\"Blocos, Vigas e Cortinas de Fundação :: Falhas de Concretagem e Aspecto Geral\"]":"INSTRUÇÃO:\nVisual, após a desforma, observar se não ocorreram falhas de concretagem e bicheiras.","[\"Estrutura\",\"Blocos, Vigas e Cortinas de Fundação :: Verificar a Posição da Estaca em Relação Ao Bloco\"]":"INSTRUÇÃO:\nChecar visualmente.","[\"Estrutura\",\"Lajes :: Cabo de Aço para Atrelar O Cinto de Segurança – Linha de Vida\"]":"INSTRUÇÃO:\nVisual, antes do início da montagem do assoalho.","[\"Estrutura\",\"Lajes :: Transferência dos Eixos Principais (para Assoalho)\"]":"INSTRUÇÃO:\nAtravés de fio de prumo a laser em relação ao eixo do pavimento inferior. Verificar o esquadro e a distância entre os eixos.\n\nTOLERÂNCIA:\n± 3 mm","[\"Estrutura\",\"Lajes :: Posicionamento do Assoalho em Relação Aos Eixos Principais\"]":"INSTRUÇÃO:\nAtravés de trena metálica, conferir todas as dimensões geométricas definidas no projeto de formas.\n\nTOLERÂNCIA:\n± 3 mm","[\"Estrutura\",\"Lajes :: Escoramento\"]":"INSTRUÇÃO:\nVerificar visualmente se o posicionamento e a quantidade de pontos atendem ao projeto.","[\"Estrutura\",\"Lajes :: Armação\"]":"INSTRUÇÃO:\nChecar se a amarração está firme, se o cobrimento está conforme o projeto, verificar a quantidade e a bitola das barras, os apoios da armação negativa, a limpeza e a ausência de oxidação/perda de seção na armadura. Verificar se as dimensões das peças estão conforme projeto e se a armadura foi amarrada.","[\"Estrutura\",\"Lajes :: Arranques\"]":"INSTRUÇÃO:\nChecar o arranque das lajes de acordo com o projeto de armação e a continuidade da estrutura.","[\"Estrutura\",\"Lajes :: Itens de Segurança\"]":"INSTRUÇÃO:\nVerificar os itens aplicáveis à obra: fita de ancoragem, gancho de SLQA, gancho piso a piso e bandeja.","[\"Estrutura\",\"Lajes :: Passagens em Lajes\"]":"INSTRUÇÃO:\nVerificar com o auxílio de trena metálica o posicionamento e as dimensões das passagens de hidráulica, elétrica e linha de vida. Verificar também a existência de reforço de armação.\n\nTOLERÂNCIA:\n± 3 mm","[\"Estrutura\",\"Lajes :: Travamento e Encaixe dos Painéis e Nivelamento das Lajes\"]":"INSTRUÇÃO:\nChecar o travamento das formas e verificar o nivelamento das lajes pelo pavimento inferior.","[\"Estrutura\",\"Lajes :: Limpeza do Assoalho\"]":"INSTRUÇÃO:\nVisual, checando a limpeza do assoalho e aplicação do desmoldante nas chapas.","[\"Estrutura\",\"Lajes :: Componentes Embutidos\"]":"INSTRUÇÃO:\nHavendo componentes embutidos de material metálico, verificar visualmente se possuem proteção contra corrosão.","[\"Estrutura\",\"Lajes :: Lançamento do Concreto\"]":"INSTRUÇÃO:\nVerificar o adensamento do concreto durante a concretagem. Conferir na execução se a galga de concreto atende às medidas definidas no projeto estrutural.","[\"Estrutura\",\"Lajes :: Cura Química\"]":"INSTRUÇÃO:\nApós a pega do concreto (secagem ao tato), iniciar a cura química da laje por 24 horas no mínimo.","[\"Estrutura\",\"Lajes :: Reescoramento\"]":"INSTRUÇÃO:\nVisual no local, antes do início da desforma, conforme projeto ou orientação do projetista. Verificar se a distância entre as peças atende ao projeto de reescoramento.","[\"Estrutura\",\"Lajes :: Falhas de Concretagem e Aspecto Geral da Laje\"]":"INSTRUÇÃO:\nVisual, após a desforma, observar se não ocorreram bicheiras, flechas maiores que as definidas em projeto, cantos quebrados, fissuras, dentes e embarrigamentos.","[\"Estrutura\",\"Lajes :: Limpeza dos Painéis\"]":"INSTRUÇÃO:\nVisual, observando se as peças necessitam de reparos ou troca, para liberação da próxima montagem de formas.","[\"Estrutura\",\"Pilares :: Cabo de Aço para Atrelar O Cinto de Segurança\"]":"INSTRUÇÃO:\nVisual, após montagem da laje inferior.","[\"Estrutura\",\"Pilares :: Transferência dos Eixos Principais (para Gastalho)\"]":"INSTRUÇÃO:\nAtravés de fio de prumo ou prumo a laser em relação ao eixo do pavimento inferior. Verificar o esquadro e a distância entre eixos.\n\nTOLERÂNCIA:\n± 3 mm","[\"Estrutura\",\"Pilares :: Checagem dos Gastalhos\"]":"INSTRUÇÃO:\nVerificar a locação dos gastalhos através dos eixos, utilizando trena metálica.\n\nTOLERÂNCIA:\n± 3 mm","[\"Estrutura\",\"Pilares :: Aplicação do Desmoldante\"]":"INSTRUÇÃO:\nVerificar se foi aplicado desmoldante nas formas antes do seu fechamento.","[\"Estrutura\",\"Pilares :: Armação\"]":"INSTRUÇÃO:\nChecar se a amarração está firme, se o cobrimento está conforme projeto, verificar a quantidade e a bitola das barras e a limpeza. Verificar ausência de oxidação/perda de seção na armadura e se as dimensões das peças estão conforme projeto.","[\"Estrutura\",\"Pilares :: Barra de Aço do para Raio\"]":"INSTRUÇÃO:\nChecar o posicionamento das barras de para-raio indicadas pelo projeto de elétrica.","[\"Estrutura\",\"Pilares :: Limpeza e Vedação dos Pés dos Pilares\"]":"INSTRUÇÃO:\nVisual, após a montagem das formas do pilar, verificar a vedação e limpeza dos pés dos pilares.","[\"Estrutura\",\"Pilares :: Posicionamento dos Pilares em Relação Aos Eixos Principais\"]":"INSTRUÇÃO:\nAtravés de trena metálica, conferir todas as dimensões geométricas definidas no projeto de formas.\n\nTOLERÂNCIA:\n± 3 mm","[\"Estrutura\",\"Pilares :: Travamento e Encaixe dos Painéis dos Pilares\"]":"INSTRUÇÃO:\nVisual, após o travamento final das formas, checando o fechamento com os mosquitos.","[\"Estrutura\",\"Pilares :: Componentes Embutidos\"]":"INSTRUÇÃO:\nHavendo componentes embutidos de material metálico, verificar visualmente se possuem proteção contra corrosão.","[\"Estrutura\",\"Pilares :: Prumo dos Pilares\"]":"INSTRUÇÃO:\nFio de prumo e trena metálica.\n\nTOLERÂNCIA:\n± 3 mm","[\"Estrutura\",\"Pilares :: Cura do Concreto\"]":"INSTRUÇÃO:\nVerificar se a cura do concreto está de acordo com as especificações do projeto.","[\"Estrutura\",\"Pilares :: Falhas de Concretagem\"]":"INSTRUÇÃO:\nVisual, após desforma, observar se não ocorreram bicheiras e se foram removidos todos os mosquitos.","[\"Estrutura\",\"Pilares :: Aspecto Geral dos Pilares\"]":"INSTRUÇÃO:\nVisual no local, após a desforma, verificar se os pilares estão aprumados.","[\"Estrutura\",\"Vigas :: Cabo de Aço para Atrelar O Cinto de Segurança – Linha de Vida\"]":"INSTRUÇÃO:\nVisual, após montagem da laje inferior.","[\"Estrutura\",\"Vigas :: Transferência dos Eixos Principais (para Assoalho)\"]":"INSTRUÇÃO:\nAtravés de fio de prumo ou prumo a laser em relação ao eixo do pavimento inferior. Verificar o esquadro e a distância entre eixos.\n\nTOLERÂNCIA:\n± 3 mm","[\"Estrutura\",\"Vigas :: Posicionamento das Vigas em Relação Aos Eixos Principais\"]":"INSTRUÇÃO:\nAtravés de trena metálica, conferir todas as dimensões geométricas definidas no projeto de formas.\n\nTOLERÂNCIA:\n± 3 mm","[\"Estrutura\",\"Vigas :: Aplicação do Desmoldante\"]":"INSTRUÇÃO:\nVerificar se foi aplicado desmoldante nas formas antes do seu fechamento.","[\"Estrutura\",\"Vigas :: Armação\"]":"INSTRUÇÃO:\nChecar se a amarração está firme, se o cobrimento está conforme projeto, verificar a quantidade e a bitola das barras. Verificar se não há oxidação e perda de seção na armadura. Verificar se as dimensões das peças estão conforme projeto.","[\"Estrutura\",\"Vigas :: Aterramento\"]":"INSTRUÇÃO:\nVerificar se o aterramento dos gradis e caixilhos está de acordo com o projeto.","[\"Estrutura\",\"Vigas :: Arranques\"]":"INSTRUÇÃO:\nChecar os arranques das vigas de acordo com o projeto de armação e a continuidade da estrutura.","[\"Estrutura\",\"Vigas :: Componentes Embutidos\"]":"INSTRUÇÃO:\nHavendo componentes embutidos de material metálico, verificar visualmente se possuem proteção contra corrosão.","[\"Estrutura\",\"Vigas :: Escoramento\"]":"INSTRUÇÃO:\nVerificar visualmente se o posicionamento e a quantidade de pontos atendem ao projeto.","[\"Estrutura\",\"Vigas :: Passagens em Vigas\"]":"INSTRUÇÃO:\nVerificar com o auxílio de trena metálica o posicionamento e as dimensões das passagens de hidráulica e elétrica. Verificar também a existência de reforço na armação.\n\nTOLERÂNCIA:\n± 3 mm","[\"Estrutura\",\"Vigas :: Travamento e Encaixe dos Painéis e Nivelamento das Vigas\"]":"INSTRUÇÃO:\nChecar o travamento final das formas, checando o fechamento com mosquitos, e verificar o nivelamento das vigas pelo pavimento inferior.","[\"Estrutura\",\"Vigas :: Limpeza do Assoalho\"]":"INSTRUÇÃO:\nVisual, checando a limpeza do assoalho e aplicação do desmoldante nas chapas.","[\"Estrutura\",\"Vigas :: Reescoramento\"]":"INSTRUÇÃO:\nVisual no local, após o final da desforma, conforme projeto ou orientação do projetista.","[\"Estrutura\",\"Vigas :: Cura do Concreto\"]":"INSTRUÇÃO:\nVerificar se a cura do concreto está de acordo com as especificações do projeto.","[\"Estrutura\",\"Vigas :: Falhas de Concretagem e Aspecto Geral das Vigas\"]":"INSTRUÇÃO:\nVisual, após a desforma, observar se não ocorreram bicheiras e se as vigas estão alinhadas/aprumadas e niveladas.","[\"Esquadrias\",\"Taliscas e Contramarco :: Condições para Início do Serviço\"]":"INSTRUÇÃO:\nAs superfícies de concreto devem estar chapiscadas. Elevação da alvenaria concluída. Cota de referência definida e marcada na estrutura (tinta vermelha).","[\"Esquadrias\",\"Taliscas e Contramarco :: Personalização\"]":"INSTRUÇÃO:\nConfirmação dos acabamentos dos ambientes para personalização (para ajustar a folga do contramarco em relação à espessura do revestimento).","[\"Esquadrias\",\"Taliscas e Contramarco :: Prumo das Taliscas\"]":"INSTRUÇÃO:\nVerificar por meio de uma régua com bolha acoplada o prumo das taliscas.\n\nTOLERÂNCIA:\nBolha entre linhas","[\"Esquadrias\",\"Taliscas e Contramarco :: Esquadro das Taliscas\"]":"INSTRUÇÃO:\nVerificar por meio de uma régua de alumínio e esquadro metálico de 60x80.\n\nTOLERÂNCIA:\n± 3 mm (na ponta de 60)","[\"Esquadrias\",\"Taliscas e Contramarco :: Esquadro do Contramarco em Relação à Fachada\"]":"INSTRUÇÃO:\nVerificar com auxílio de esquadro e trena metálica o esquadro formado entre o contramarco e o arame da fachada.\n\nTOLERÂNCIA:\n3 mm","[\"Esquadrias\",\"Taliscas e Contramarco :: Altura do Vão em Relação Ao Piso Acabado\"]":"INSTRUÇÃO:\nMedir com trena e comparar com a altura de projeto, através da cota de referência marcada na estrutura.\n\nTOLERÂNCIA:\n± 3 mm","[\"Esquadrias\",\"Taliscas e Contramarco :: Grapas\"]":"INSTRUÇÃO:\nVerificar visualmente se a quantidade de grapas é suficiente em relação ao tamanho do contramarco.","[\"Esquadrias\",\"Taliscas e Contramarco :: Nivelamento das Travessas\"]":"INSTRUÇÃO:\nUtilizando nível de bolhas.\n\nTOLERÂNCIA:\nBolha entre linhas","[\"Esquadrias\",\"Taliscas e Contramarco :: Checar Prumo e Esquadro do Contramarco\"]":"INSTRUÇÃO:\nUtilizando prumo de face ou régua de bolha e esquadro de alumínio.\n\nTOLERÂNCIA:\n± 3 mm / bolha entre linhas","[\"Esquadrias\",\"Taliscas e Contramarco :: Checar O Chumbamento com O Gabarito. Remoção das Fitas Hellerman\"]":"INSTRUÇÃO:\nVisual. Após a instalação do contramarco, checar se a fita foi removida corretamente.","[\"Gesso\",\"Gesso Liso :: Condições para Início do Serviço\"]":"INSTRUÇÃO:\nVerificar no laudo de acústica se alguma parede tem material e espessura diferentes das demais. O encunhamento da parede deve estar todo executado, e a superfície das juntas totalmente preenchida. As superfícies de concreto devem estar chapiscadas. Verificar visualmente se foram removidas sujeiras, incrustações, pregos etc. Verificar se as instalações elétricas e pontos de luz estão protegidos. Conferência de taliscas e mestras concluídas, e conferir o traço da produção de argamassa/gesso.","[\"Gesso\",\"Gesso Liso :: Planicidade\"]":"INSTRUÇÃO:\nVerificar por meio de régua de alumínio na diagonal da parede.\n\nTOLERÂNCIA:\n± 3 mm","[\"Gesso\",\"Gesso Liso :: Nivelamento e Prumo\"]":"INSTRUÇÃO:\nVerificar por meio de régua com nível de bolha o nivelamento e prumo da camada de revestimento.","[\"Gesso\",\"Gesso Liso :: Esquadro\"]":"INSTRUÇÃO:\nVerificar por meio de esquadro metálico os encontros entre paredes e tetos.\n\nTOLERÂNCIA:\n± 3 mm","[\"Gesso\",\"Gesso Liso :: Cantos Riscados\"]":"INSTRUÇÃO:\nVerificar visualmente se os cantos entre paredes e tetos estão riscados.","[\"Gesso\",\"Gesso Liso :: Tela Entre Alvenaria e Estrutura\"]":"INSTRUÇÃO:\nVerificar visualmente se a tela foi aplicada nos encontros da alvenaria com a estrutura, no 1º e nos 2 últimos andares dos apartamentos, onde é aplicada massa.","[\"Gesso\",\"Gesso Liso :: Aspecto Final\"]":"INSTRUÇÃO:\nVerificar visualmente se há ondulações no revestimento, e o acabamento de cantos, batentes e contramarcos, arremates das caixas e pontos de elétrica.","[\"Revestimento\",\"Massa Interna :: Condições para Início do Serviço\"]":"INSTRUÇÃO:\nVerificar no laudo de acústica se alguma parede tem material e espessura diferentes das demais. O encunhamento da parede deve estar todo executado, e a superfície das juntas totalmente preenchida. As superfícies de concreto devem estar chapiscadas. Verificar visualmente se foram removidas sujeiras, incrustações, pregos etc. Verificar se as instalações elétricas e pontos de luz estão protegidos. Conferência de taliscas e mestras concluídas, e conferir o traço da produção de argamassa/gesso.","[\"Revestimento\",\"Massa Interna :: Planicidade\"]":"INSTRUÇÃO:\nVerificar por meio de régua de alumínio na diagonal da parede.\n\nTOLERÂNCIA:\n± 3 mm","[\"Revestimento\",\"Massa Interna :: Nivelamento e Prumo\"]":"INSTRUÇÃO:\nVerificar por meio de régua com nível de bolha o nivelamento e prumo da camada de revestimento.","[\"Revestimento\",\"Massa Interna :: Esquadro\"]":"INSTRUÇÃO:\nVerificar por meio de esquadro metálico os encontros entre paredes e tetos.\n\nTOLERÂNCIA:\n± 3 mm","[\"Revestimento\",\"Massa Interna :: Cantos Riscados\"]":"INSTRUÇÃO:\nVerificar visualmente se os cantos entre paredes e tetos estão riscados.","[\"Revestimento\",\"Massa Interna :: Tela Entre Alvenaria e Estrutura\"]":"INSTRUÇÃO:\nVerificar visualmente se a tela foi aplicada nos encontros da alvenaria com a estrutura, no 1º e nos 2 últimos andares dos apartamentos, onde é aplicada massa.","[\"Revestimento\",\"Massa Interna :: Aspecto Final\"]":"INSTRUÇÃO:\nVerificar visualmente se há ondulações no revestimento, e o acabamento de cantos, batentes e contramarcos, arremates das caixas e pontos de elétrica.","[\"Revestimento\",\"Massa Interna :: Verificação de Aderência\"]":"INSTRUÇÃO:\n","[\"Produção de Argamassa\",\"Condições para Início dos Serviços\"]":"INSTRUÇÃO:\nChapisco concluído.","[\"Produção de Argamassa\",\"Treinamento\"]":"INSTRUÇÃO:\nVerificar se o funcionário responsável pela mistura da argamassa está treinado pelo consultor de fachada e/ou equipe da obra. Identificar com placa no misturador nome dos funcionários treinados.","[\"Produção de Argamassa\",\"Equipamentos\"]":"INSTRUÇÃO:\nVerificar se o misturador de argamassa está sendo utilizado na capacidade adequada de forma que apareçam as facas.","[\"Produção de Argamassa\",\"Traço/Ordem de Mistura\"]":"INSTRUÇÃO:\nVerificar se o traço utilizado corresponde ao especificado no PES – identificar com placa no misturador o traço nos casos de dosagem feita na obra.","[\"Produção de Argamassa\",\"Traço\"]":"INSTRUÇÃO:\nVerificar se o traço utilizado corresponde ao especificado no PES para o referido serviço (uma vez por semana, em qualquer dia, de preferência no início dos trabalhos do dia) – identificar com placa o traço nos casos de dosagem feita na obra.","[\"Produção de Argamassa\",\"Homogeneidade e Trabalhabilidade da Argamassa\"]":"INSTRUÇÃO:\nVisual uma vez por semana, em qualquer dia (ideal que seja no início dos trabalhos do dia).","[\"Produção de Argamassa\",\"As Demais FVS 008 Não Existem na Rede\"]":"INSTRUÇÃO:\n","[\"Produção de Argamassa\",\"Contrapiso :: Equipamento\"]":"INSTRUÇÃO:\nVerificar se o equipamento é de eixo horizontal.","[\"Produção de Argamassa\",\"Contrapiso :: Balde Dosador\"]":"INSTRUÇÃO:\nVerificar se as argamassas que usam quantidade específica de água estão sendo dosadas com baldes graduados.","[\"Produção de Argamassa\",\"Contrapiso :: Traço\"]":"INSTRUÇÃO:\nVerificar se o traço utilizado corresponde ao especificado no PES para o referido serviço (uma vez por semana, em qualquer dia, de preferência no início dos trabalhos do dia) – identificar com placa o traço nos casos de dosagem feita na obra.","[\"Produção de Argamassa\",\"Contrapiso Acústico :: Equipamento\"]":"INSTRUÇÃO:\nVerificar se o equipamento é de eixo horizontal.","[\"Produção de Argamassa\",\"Contrapiso Acústico :: Traço\"]":"INSTRUÇÃO:\nVerificar se o traço utilizado corresponde ao especificado no PES para o referido serviço (uma vez por semana, em qualquer dia, de preferência no início dos trabalhos do dia) – identificar com placa o traço nos casos de dosagem feita na obra.","[\"Produção de Argamassa\",\"Contrapiso Acústico :: Balde Dosador\"]":"INSTRUÇÃO:\nVerificar se as argamassas que usam quantidade específica de água estão sendo dosadas com baldes graduados.","[\"Produção de Argamassa\",\"Revestimento Interno :: Equipamento\"]":"INSTRUÇÃO:\nVerificar se o equipamento é de eixo horizontal.","[\"Produção de Argamassa\",\"Revestimento Interno :: Traço\"]":"INSTRUÇÃO:\nVerificar se o traço utilizado corresponde ao especificado no PES para o referido serviço (uma vez por semana, em qualquer dia, de preferência no início dos trabalhos do dia) – identificar com placa o traço nos casos de dosagem feita na obra.","[\"Produção de Argamassa\",\"Revestimento Interno :: Balde Dosador\"]":"INSTRUÇÃO:\nVerificar se as argamassas que usam quantidade específica de água estão sendo dosadas com baldes graduados.","[\"Produção de Argamassa\",\"Colante :: Equipamento\"]":"INSTRUÇÃO:\nVerificar se o equipamento é de eixo horizontal.","[\"Produção de Argamassa\",\"Colante :: Balde Dosador\"]":"INSTRUÇÃO:\nVerificar se as argamassas que usam quantidade específica de água estão sendo dosadas com baldes graduados.","[\"Produção de Argamassa\",\"Colante :: Traço\"]":"INSTRUÇÃO:\nVerificar se o traço utilizado corresponde ao especificado no PES para o referido serviço (uma vez por semana, em qualquer dia, de preferência no início dos trabalhos do dia) – identificar com placa o traço nos casos de dosagem feita na obra.","[\"Produção de Argamassa\",\"Assentamento de Alvenaria :: Traço\"]":"INSTRUÇÃO:\nVerificar se o traço utilizado corresponde ao especificado no PES para o referido serviço (uma vez por semana, em qualquer dia, de preferência no início dos trabalhos do dia) – identificar com placa o traço nos casos de dosagem feita na obra.","[\"Produção de Argamassa\",\"Assentamento de Alvenaria :: Balde Dosador\"]":"INSTRUÇÃO:\nVerificar se as argamassas que usam quantidade específica de água estão sendo dosadas com baldes graduados.","[\"Produção de Argamassa\",\"Assentamento de Alvenaria :: Equipamento\"]":"INSTRUÇÃO:\nVerificar se o equipamento é de eixo horizontal.","[\"Produção de Argamassa\",\"Revestimento Externo (Piscina) :: Equipamento\"]":"INSTRUÇÃO:\nVerificar se o equipamento é de eixo horizontal.","[\"Produção de Argamassa\",\"Revestimento Externo (Piscina) :: Balde Dosador\"]":"INSTRUÇÃO:\nVerificar se as argamassas que usam quantidade específica de água estão sendo dosadas com baldes graduados.","[\"Produção de Argamassa\",\"Revestimento Externo (Piscina) :: Traço\"]":"INSTRUÇÃO:\nVerificar se o traço utilizado corresponde ao especificado no PES para o referido serviço (uma vez por semana, em qualquer dia, de preferência no início dos trabalhos do dia) – identificar com placa o traço nos casos de dosagem feita na obra.","[\"Produção de Argamassa\",\"Revestimento Externo :: Treinamento\"]":"INSTRUÇÃO:\nVerificar se o funcionário responsável pela mistura da argamassa está treinado pelo consultor de fachada e/ou equipe da obra. Identificar com placa no misturador nome dos funcionários treinados.","[\"Produção de Argamassa\",\"Revestimento Externo :: Equipamentos\"]":"INSTRUÇÃO:\nVerificar se o misturador de argamassa está sendo utilizado na capacidade adequada de forma que apareçam as facas.","[\"Produção de Argamassa\",\"Revestimento Externo :: Condição para Início de Serviço\"]":"INSTRUÇÃO:\nChapisco concluído.","[\"Produção de Argamassa\",\"Revestimento Externo :: Traço / Ordem de Mistura\"]":"INSTRUÇÃO:\nVerificar se o traço utilizado corresponde ao especificado no PES – identificar com placa no misturador o traço nos casos de dosagem feita na obra.","[\"Serviços Preliminares\",\"Locação de Obra - Gabarito :: Condições para Início dos Serviços\"]":"INSTRUÇÃO:\nChecar se o nível do gabarito confere com o levantamento planialtimétrico.","[\"Serviços Preliminares\",\"Locação de Obra - Gabarito :: Calibração de Equipamento Topográfico\"]":"INSTRUÇÃO:\nDeverá ser anexado a esta FVS o laudo de calibração da estação total que fará a locação da obra, com aferição bienal.","[\"Serviços Preliminares\",\"Locação de Obra - Gabarito :: Definição do Nível de Referência\"]":"INSTRUÇÃO:\nVisual, antes do início da locação, transferir nível para gabarito.","[\"Serviços Preliminares\",\"Locação de Obra - Gabarito :: Fixação, Travamento, Alinhamento e Nível da Tabeira\"]":"INSTRUÇÃO:\nPor meio de linha e nível de mangueira ou laser, após a sua conclusão.\n\nTOLERÂNCIA:\n3 cm em 20 metros","[\"Serviços Preliminares\",\"Locação de Obra - Gabarito :: Esquadro do Gabarito em Três Eixos Diferentes\"]":"INSTRUÇÃO:\nPor triangulação (3, 4 e 5 m).\n\nTOLERÂNCIA:\n± 3 mm","[\"Serviços Preliminares\",\"Locação de Obra - Gabarito :: Distância Entre Eixos de Pilares\"]":"INSTRUÇÃO:\nTrena, seguindo projeto de locação de pilares (na medida acumulada). Critério de aceitação: ± 5 mm.\n\nTOLERÂNCIA:\n± 5 mm","[\"Serviços Preliminares\",\"Locação de Obra - Gabarito :: Distância de Divisas e Recuos\"]":"INSTRUÇÃO:\nTrena, seguindo projeto de prefeitura aprovado.\n\nTOLERÂNCIA:\n0.02","[\"Serviços Preliminares\",\"Locação de Obra - Gabarito :: Inspeção Amostral\"]":"INSTRUÇÃO:\nVerificar por meio de trena metálica e estação total, de forma amostral, as medidas angulares e lineares cotadas no desenho com as medidas obtidas pelas diferenças de coordenadas dos eixos principais do projeto.","[\"Contrapiso\",\"Contrapiso :: Condições para Início dos Serviços\"]":"INSTRUÇÃO:\nVerificar se o ambiente está limpo e a área está desobstruída, e conferir o traço no PES de produção de argamassa. Verificar o laudo de acústica para espessura mínima.","[\"Contrapiso\",\"Contrapiso :: Tela Soldada (para Locais de Execução Sobre Camada de Regularização)\"]":"INSTRUÇÃO:\nVerificar se as telas soldadas atendem às especificações do projeto e procedimento em quantidade e posicionamento.","[\"Contrapiso\",\"Contrapiso :: Nível das Taliscas\"]":"INSTRUÇÃO:\nApós o mapeamento da laje, executar taliscas através de nível de mangueira ou nível a laser, considerando o caimento dos ralos sekapiso, se houver.\n\nTOLERÂNCIA:\n5 mm","[\"Contrapiso\",\"Contrapiso :: Acabamento da Superfície\"]":"INSTRUÇÃO:\nVisual, após a conclusão do contrapiso.","[\"Contrapiso\",\"Contrapiso :: Planicidade\"]":"INSTRUÇÃO:\nCom régua metálica, verificar a planicidade do contrapiso.\n\nTOLERÂNCIA:\n3 mm","[\"Contrapiso\",\"Contrapiso :: Caimento em Direção Aos Ralos\"]":"INSTRUÇÃO:\nVerificar se há caimento nos locais de 0,5% ou conforme definição do projeto. Para inspeção, usar régua metálica ou jogar água — neste caso, não deve formar poças ao redor do ralo.","[\"Contrapiso\",\"Contrapiso :: Aderência com a Base\"]":"INSTRUÇÃO:\nAtravés de batidas no piso, verificando se não há som \"oco\", uma semana após a conclusão do contrapiso.","[\"Contrapiso\",\"Contrapiso Acústico :: Condições para Início dos Serviços\"]":"INSTRUÇÃO:\nVerificar se o ambiente está limpo e a área está desobstruída e conferir a produção de argamassa e adição de fibra.","[\"Contrapiso\",\"Contrapiso Acústico :: Nível das Taliscas\"]":"INSTRUÇÃO:\nApós mapeamento da laje executar taliscas através de nível de mangueira ou laser.\n\nTOLERÂNCIA:\nEspessura ≥ 4,0 cm","[\"Contrapiso\",\"Contrapiso Acústico :: Manta Acústica\"]":"INSTRUÇÃO:\nVerificar se toda a área onde será executado o contrapiso está coberta pela manta acústica e se existe o transpasse de manta entre o piso e o rodapé.","[\"Contrapiso\",\"Contrapiso Acústico :: Tela Metálica\"]":"INSTRUÇÃO:\nVerificar se foram colocadas as telas nos cantos vivos e na emenda do piso aderido com o não aderido.","[\"Contrapiso\",\"Contrapiso Acústico :: Planicidade\"]":"INSTRUÇÃO:\nCom régua metálica, verificar a planicidade do contrapiso.\n\nTOLERÂNCIA:\n3 mm","[\"Contrapiso\",\"Contrapiso Acústico :: Acabamento da Superfície\"]":"INSTRUÇÃO:\nVisual após a conclusão do contrapiso mantendo junta de dilatação aproximadamente a cada 3 m.","[\"Revestimento\",\"Piso Cerâmico :: Condição para Início dos Serviços\"]":"INSTRUÇÃO:\nVerificar se o ambiente está limpo, a área está desobstruída e a impermeabilização finalizada. Conferir a paginação dos pisos com o projeto de arquitetura, o lote e a especificação do revestimento.","[\"Revestimento\",\"Piso Cerâmico :: Juntas\"]":"INSTRUÇÃO:\nApós assentadas todas as peças, antes do rejunte, verificar a espessura e o alinhamento das juntas e dentes sobressalentes.\n\nTOLERÂNCIA:\n1 mm","[\"Revestimento\",\"Piso Cerâmico :: Planicidade e Nivelamento\"]":"INSTRUÇÃO:\nVerificar por meio de régua metálica a planicidade do revestimento. Verificar por meio de nível a laser ou régua de bolha o nivelamento do revestimento.\n\nTOLERÂNCIA:\n3 mm planicidade / 5 mm nivelamento","[\"Revestimento\",\"Piso Cerâmico :: Condição para Rejuntamento\"]":"INSTRUÇÃO:\nO início do rejuntamento deverá ser 3 dias após o assentamento da cerâmica. Limpar e umedecer as juntas e preparar o produto conforme instruções do fabricante.","[\"Revestimento\",\"Piso Cerâmico :: Aspecto Final\"]":"INSTRUÇÃO:\nVerificar visualmente o preenchimento das juntas entre peças (sem falhas por falta ou excesso de rejunte) e a limpeza das peças e do rejunte. Verificar se após o rejuntamento apareceu diferença de tonalidade ou presença de defeitos, quebras e lascas nas peças. Verificar com auxílio de martelo de borracha ou cabo de vassoura a aderência das placas na superfície.\n\nTOLERÂNCIA:\nNão pode haver som cavo em mais de um ponto por peça","[\"Revestimento\",\"Piso Cerâmico :: Caimento\"]":"INSTRUÇÃO:\nVerificar por meio de nível a laser ou água o caimento para os ralos nas áreas molhadas e molháveis (quando indicado em projeto).\n\nTOLERÂNCIA:\nNão deve formar lâmina de água nos cantos; a água deve seguir para o ralo","[\"Revestimento\",\"Piso Cerâmico :: Proteção\"]":"INSTRUÇÃO:\nVerificar a proteção com lona plástica ou papelão após a conclusão do serviço.","[\"Revestimento\",\"Parede em Cerâmica :: Condição para Início dos Serviços\"]":"INSTRUÇÃO:\nVerificar se o ambiente está limpo, a área está desobstruída e a impermeabilização finalizada. Conferir a paginação dos azulejos com o projeto de arquitetura, o lote e a especificação do revestimento.","[\"Revestimento\",\"Parede em Cerâmica :: Juntas\"]":"INSTRUÇÃO:\nApós assentadas todas as peças, antes do rejunte, verificar a espessura e o alinhamento das juntas e dentes sobressalentes.\n\nTOLERÂNCIA:\n2 mm","[\"Revestimento\",\"Parede em Cerâmica :: Planicidade e Prumo do Revestimento\"]":"INSTRUÇÃO:\nVerificar por meio de régua metálica a planicidade do revestimento. Verificar o prumo do revestimento com régua com nível de bolha.\n\nTOLERÂNCIA:\nBolha entre as linhas","[\"Revestimento\",\"Parede em Cerâmica :: Aderência das Placas\"]":"INSTRUÇÃO:\nRemover uma placa assentada no máximo há 30 minutos, escolhida ao acaso, que deve ter o tardoz inteiramente impregnado de argamassa colante. Verificar também com auxílio de martelo de borracha ou cabo de vassoura a aderência das placas na superfície.","[\"Revestimento\",\"Parede em Cerâmica :: Aspecto Final\"]":"INSTRUÇÃO:\nApós o término do serviço, verificar visualmente a regularidade do acabamento das juntas, dos cantos, dos recortes, os arremates e a tonalidade das peças.","[\"Revestimento\",\"Parede em Cerâmica :: Condição para Rejuntamento\"]":"INSTRUÇÃO:\nO início do rejuntamento deverá ser 3 dias após o assentamento da cerâmica. Limpar e umedecer as juntas e preparar o produto conforme instruções do fabricante.","[\"Revestimento\",\"Parede em Cerâmica :: Aspecto Final (Após Rejuntamento)\"]":"INSTRUÇÃO:\nVerificar visualmente o preenchimento das juntas entre peças (sem falhas por falta ou excesso de rejunte) e a limpeza das peças e do rejunte.","[\"Revestimento\",\"Externo em Argamassa :: Passantes na Fachada\"]":"INSTRUÇÃO:\nVerificar se o duto de exaustão possui inclinação suficiente para evitar entrada de água e se está no mesmo alinhamento.","[\"Revestimento\",\"Externo em Argamassa :: Condições para Início do Serviço\"]":"INSTRUÇÃO:\nVerificar visualmente se foram removidas as sujeiras, se o chapisco foi executado, se há proteções nos vãos e nos serviços acabados, a alvenaria fixada, preenchimento dos furos, se foi passado zarcão nas pontas de ferro. Conferência da produção da argamassa.","[\"Revestimento\",\"Externo em Argamassa :: Tela Metálica\"]":"INSTRUÇÃO:\nVerificar visualmente se foram instaladas telas metálicas na fachada entre a alvenaria e estrutura, sob vãos de janelas ou conforme especificado no projeto de fachada.","[\"Revestimento\",\"Externo em Argamassa :: Ensaio de Aderência\"]":"INSTRUÇÃO:\nVerificar 12 amostras do revestimento, devendo pelo menos 8 atender a resistência mínima de 0,30 MPa aos 28 dias.","[\"Revestimento\",\"Externo em Argamassa :: Aspecto Final\"]":"INSTRUÇÃO:\nApós o término do serviço, verificar visualmente o aspecto final, alinhamento e tratamento com selante dos frisos e desnível de requadrações para escoamento de água (sacadas e vãos de janela).\n\nTOLERÂNCIA:\n± 3 mm","[\"Revestimento\",\"Externo em Argamassa :: Planicidade, Prumo e Alinhamento\"]":"INSTRUÇÃO:\nApós o término do serviço, antes de descer o balancim para a próxima área, verificar visualmente seu alinhamento em relação aos prumos. Verificar por meio de régua metálica a planicidade do revestimento. Verificar o prumo com régua de bolha.\n\nTOLERÂNCIA:\nPrumo: 3 mm. Planicidade: 3 mm.","[\"Revestimento\",\"Externo em Argamassa :: Relatório de Execução\"]":"INSTRUÇÃO:\nSolicitar ao executante do serviço o relatório de aplicação do revestimento, contendo as seguintes informações: preparo da base segundo especificação de projeto ou outros para correção de nível, prumo e planeza; espessura do revestimento ou de camadas do revestimento; correções ou reparos eventualmente realizados ao longo do serviço.","[\"Revestimento\",\"Externo em Argamassa :: Posicionamento dos Arames\"]":"INSTRUÇÃO:\nElaborar mapeamento dos prumos e requadração de vãos com medidas de espessura de massa em todos os andares.\n\nTOLERÂNCIA:\n3 ≤ e ≤ 5 cm","[\"Revestimento\",\"Externo em Argamassa :: Espessura do Revestimento\"]":"INSTRUÇÃO:\nVerificar se o revestimento possui entre 3 cm e 5 cm ou conforme especificações do projeto.","[\"Revestimento\",\"Externo em Argamassa :: Requadração dos Vãos\"]":"INSTRUÇÃO:\nVerificar a requadração e vão conforme tipo de janela conforme PES 013.","[\"Revestimento\",\"Pastilha :: Condição para Início dos Serviços\"]":"INSTRUÇÃO:\nVerificar se a base está limpa e o revestimento liberado há 1 semana.","[\"Revestimento\",\"Pastilha :: Resistência de Aderência (Fachada)\"]":"INSTRUÇÃO:\nPara ensaio de resistência superficial é necessário ensaiar 12 amostras. Para ensaio de aderência das placas ao emboço é necessário ensaiar 12 amostras.\n\nTOLERÂNCIA:\nResistência superficial: 8 amostras com CP ≥ 0,5 MPa. Aderência das placas: 8 amostras com CP ≥ 0,5 MPa","[\"Revestimento\",\"Pastilha :: Preenchimento do Tardoz\"]":"INSTRUÇÃO:\nVerificar em duas placas se o preenchimento do tardoz possui área maior que 90%. Em caso de reprovação, realizar novo teste em quatro placas — devem-se aprovar três placas com área de no mínimo 90%.\n\nTOLERÂNCIA:\n≥ 90% da área","[\"Revestimento\",\"Pastilha :: Juntas de Dilatação\"]":"INSTRUÇÃO:\nVerificar conforme projeto ou procedimento PES.014 – Revestimento em Pastilhas para Fachadas e Piscina.","[\"Revestimento\",\"Pastilha :: Vãos (Fachada)\"]":"INSTRUÇÃO:\nApós o término do serviço, verificar com uma trena o desnível do revestimento nos vãos.\n\nTOLERÂNCIA:\n± 3 mm","[\"Revestimento\",\"Pastilha :: Aderência das Pastilhas\"]":"INSTRUÇÃO:\nVerificar com auxílio de cabo de madeira ou martelo de plástico/duto se há som cavo no pano executado.","[\"Revestimento\",\"Pastilha :: Aspecto Final\"]":"INSTRUÇÃO:\nApós assentadas todas as peças, verificar visualmente se as juntas estão niveladas e uniformes, além de suas dimensões (conforme projeto), a planicidade e ressaltos. Verificar o prumo do revestimento com prumo de face ou régua com nível de bolha. Verificar o rejunte e tratamento das juntas.\n\nTOLERÂNCIA:\n3 mm de planicidade; 3 mm de prumo; 1 mm de ressaltos","[\"Revestimento\",\"Pastilha :: Condição para Rejuntamento\"]":"INSTRUÇÃO:\nO início do rejuntamento deverá ser 3 dias após o assentamento da pastilha. Limpar e umedecer as juntas e preparar o produto conforme instruções do fabricante.","[\"Revestimento\",\"Pastilha :: Aspecto Final (Após Rejuntamento)\"]":"INSTRUÇÃO:\nVerificar visualmente o preenchimento das juntas entre peças (sem falhas por falta ou excesso de rejunte) e a limpeza das peças e do rejunte.","[\"Pedra Natural\",\"Piso :: Condição para Início dos Serviços\"]":"INSTRUÇÃO:\nVerificar se a demarcação da paginação, os níveis e caimentos estão definidos. Checar também se o ambiente está limpo e desobstruído. No caso de piscinas, verificar se as bordas foram boleadas. Verificar se os batentes metálicos e contramarcos estão instalados e conferidos.","[\"Pedra Natural\",\"Piso :: Especificações Técnicas\"]":"INSTRUÇÃO:\nVerificar se as especificações técnicas do projeto e do PES.016 - Piso Pedras Naturais foram atendidas.","[\"Pedra Natural\",\"Piso :: Tonalidade do Material\"]":"INSTRUÇÃO:\nVerificar visualmente se há divergências de tonalidade no material aplicado. (Obs: verificar se a diferença não é natural da pedra).","[\"Pedra Natural\",\"Piso :: Impermeabilização Tardoz (Costas)\"]":"INSTRUÇÃO:\nVerificar visualmente se foi aplicado o impermeabilizante corretamente, com duas demãos cruzadas.","[\"Pedra Natural\",\"Piso :: Aspecto Geral\"]":"INSTRUÇÃO:\nVerificar, visualmente, o nivelamento entre as peças, a planeza do revestimento com régua metálica, a variação na espessura das juntas, a presença de dentes ou saliências e o aspecto do rejunte. Verificar se não há fissuras e fraturas que possam danificar a integridade estrutural para o uso pretendido.\n\nTOLERÂNCIA:\n3 mm de planicidade","[\"Pedra Natural\",\"Piso :: Requisitos de Desempenho\"]":"INSTRUÇÃO:\nVerificar com régua metálica se há desníveis no piso. Verificar com auxílio de trena se há frestas nos pisos. Verificar visualmente se há arestas contundentes no piso.\n\nTOLERÂNCIA:\nDesnível máximo 5 mm. Frestas não podem ultrapassar 4 mm. Não pode haver arestas contundentes. Não pode haver bolhas, fissuras, empolamentos, destacamentos, delaminações, e florescências e desagregação superficial.","[\"Pedra Natural\",\"Piso :: Rodapés\"]":"INSTRUÇÃO:\nVerificar, visualmente, onde definido, o alinhamento e aspecto final das peças.","[\"Pedra Natural\",\"Piso :: Caimento\"]":"INSTRUÇÃO:\nJogar água na superfície, após a execução dos serviços, verificando se não há formação de poças.","[\"Pedra Natural\",\"Piso :: Juntas de Dilatação\"]":"INSTRUÇÃO:\nVerificar a necessidade de juntas de dilatação a cada mudança de revestimento, níveis e aterros.","[\"Pedra Natural\",\"Piso :: Impermeabilização de Acabamento Final\"]":"INSTRUÇÃO:\nVerificar visualmente se após a limpeza final foi aplicado o impermeabilizante de acabamento.","[\"Pedra Natural\",\"Bancadas :: Condição de Início de Serviço\"]":"INSTRUÇÃO:\nVerificar a medida da locação do(s) apoio(s) e o nível sobre o piso acabado (COZ e AS = 90 cm; BH = 85 cm por cima da cuba; BH coletivos = 78 a 80 cm; COZ acessíveis = 85 cm).\n\nTOLERÂNCIA:\n± 5 mm","[\"Pedra Natural\",\"Bancadas :: Nível da Bancada\"]":"INSTRUÇÃO:\nApós a conclusão do serviço, verificar por meio de nível de bolha o nivelamento do conjunto.\n\nTOLERÂNCIA:\nBolha entre linhas","[\"Pedra Natural\",\"Bancadas :: Aspecto Final da Bancada\"]":"INSTRUÇÃO:\nApós a conclusão do serviço, verificar visualmente: o chumbamento da posição da cuba de inox, a limpeza das juntas, a firmeza do conjunto, a proteção da peça e o rejuntamento.","[\"Esquadrias\",\"Colocação de Batente Metálico :: Sentido de Abertura da Porta\"]":"INSTRUÇÃO:\nVerificar visualmente se o batente foi instalado no sentido correto de abertura da porta, conforme projeto de bombeiro.","[\"Esquadrias\",\"Colocação de Batente Metálico :: Preenchimento da Argamassa\"]":"INSTRUÇÃO:\nVerificar visualmente se, nas ombreiras, testeiras e grapas, foi realizado o preenchimento completo de argamassa.","[\"Esquadrias\",\"Colocação de Batente Metálico :: Prumo e Nível\"]":"INSTRUÇÃO:\nVerificar o prumo e nível das ombreiras, com uma régua de nível.\n\nTOLERÂNCIA:\nBolha entre linhas","[\"Esquadrias\",\"Colocação de Batente Metálico :: Fixação\"]":"INSTRUÇÃO:\nVerificar visualmente o aspecto final após a fixação e verificar falhas de chumbamento.","[\"Esquadrias\",\"Caixilho de Alumínio :: Condição para Início de Serviço\"]":"INSTRUÇÃO:\nContramarco chumbado, requadração dos vãos finalizada, limpeza dos contramarcos concluída. Verificar laudo de acústica para espessura do vidro.","[\"Esquadrias\",\"Caixilho de Alumínio :: Verificar Se Os Caixilhos Funcionam Corretamente\"]":"INSTRUÇÃO:\nTestar a abertura e fechamento das folhas, fechaduras e maçanetas (quando houver).","[\"Esquadrias\",\"Caixilho de Alumínio :: Verificar Se Os Vidros e O Perfil Não Estão Riscados, Trincados ou Quebrados. Checar Se a Vedação da Esquadria Foi Executada Corretamente\"]":"INSTRUÇÃO:\nVerificação visual.","[\"Esquadrias\",\"Caixilho de Alumínio :: Verificar Se as Persianas (Onde Houver) Funcionam Corretamente\"]":"INSTRUÇÃO:\nTestar, após o destravamento, a abertura e o fechamento total dos vãos da persiana.","[\"Gesso\",\"Forro de Gesso :: Condições para Início do Serviço\"]":"INSTRUÇÃO:\nLimpeza geral do ambiente. Finalização dos serviços de tubulação de hidráulica, fiação elétrica, ventilação forçada (quando houver) e ar condicionado.","[\"Gesso\",\"Forro de Gesso :: Marcação do Nível do Forro\"]":"INSTRUÇÃO:\nVerificar a marcação do nível de forro nas paredes do ambiente, a partir do nível de referência, com auxílio de nível a laser.","[\"Gesso\",\"Forro de Gesso :: Aspecto Geral\"]":"INSTRUÇÃO:\nVerificar visualmente a homogeneidade do acabamento do forro e tabicas, e se não há presença de marcas das emendas em relevo.","[\"Gesso\",\"Forro de Gesso :: Planicidade\"]":"INSTRUÇÃO:\nVerificar utilizando régua metálica.\n\nTOLERÂNCIA:\nMáximo 3 mm em 2 m","[\"Gesso\",\"Forro de Gesso :: Nivelamento\"]":"INSTRUÇÃO:\nVerificar por meio de nível a laser ou mangueira de nível o nivelamento do forro.","[\"Gesso\",\"Forro de Gesso :: Limpeza\"]":"INSTRUÇÃO:\nVerificar a limpeza do piso e dos azulejos após a conclusão do serviço.","[\"Gesso\",\"Forro em Placas de Gesso Acartonado :: Marcação do Nível do Forro\"]":"INSTRUÇÃO:\nVerificar a marcação do nível de forro nas paredes e no centro do ambiente, a partir do nível de referência, com o auxílio de nível a laser.\n\nTOLERÂNCIA:\nMáximo 5 mm em 4 metros","[\"Gesso\",\"Forro em Placas de Gesso Acartonado :: Tipo de Placa\"]":"INSTRUÇÃO:\nVerificar visualmente se a placa instalada atende ao local de uso e ao projeto (tipo RU, ST e RF). RU – resistente a umidade. RF – resistente ao fogo. ST – demais aplicações.\n\nTOLERÂNCIA:\nConforme projeto","[\"Gesso\",\"Forro em Placas de Gesso Acartonado :: Fixação da Estrutura\"]":"INSTRUÇÃO:\nVerificar se os montantes metálicos estão fixados de acordo com o espaçamento indicado.\n\nTOLERÂNCIA:\n2 cm","[\"Gesso\",\"Forro em Placas de Gesso Acartonado :: Planicidade\"]":"INSTRUÇÃO:\nVerificar utilizando-se régua de alumínio de 2 m de comprimento após o fechamento. Verificações com régua de nível bolha de 20 cm para locais onde não for possível a régua com maior dimensão.\n\nTOLERÂNCIA:\nMáximo de 3 mm (régua de 2 m). Máximo 1 mm nos 20 cm avaliados (régua com nível bolha)","[\"Gesso\",\"Forro em Placas de Gesso Acartonado :: Aspecto Geral\"]":"INSTRUÇÃO:\nVerificar visualmente a homogeneidade do forro, das fitas nas emendas, e se não há presença de marcas das emendas em relevo.","[\"Pintura\",\"PVA e Acrílica :: Condição de Início\"]":"INSTRUÇÃO:\nVerificar se o emboço, reboco ou concreto foi executado há mais de 30 dias, e o gesso há pelo menos 10 dias.","[\"Pintura\",\"PVA e Acrílica :: Preparação da Base\"]":"INSTRUÇÃO:\nVerificar visualmente se foram removidas as sujeiras antes da pintura, e se não há presença de umidade na superfície.","[\"Pintura\",\"PVA e Acrílica :: Aplicação do Selador\"]":"INSTRUÇÃO:\nVerificar visualmente se o selador foi aplicado sobre revestimentos de gesso.","[\"Pintura\",\"PVA e Acrílica :: Aspecto Final\"]":"INSTRUÇÃO:\nVerificar visualmente se a pintura está uniforme, sem falhas e escorrimentos.","[\"Pintura\",\"Tinta Esmalte Verniz :: Preparação da Base\"]":"INSTRUÇÃO:\nVerificar visualmente se foram removidas as sujeiras e partes soltas antes da pintura e tampados/cobertos os pontos falhos de solda.","[\"Pintura\",\"Tinta Esmalte Verniz :: Aplicação do Selador e/ou Fundo Anticorrosivo\"]":"INSTRUÇÃO:\nVerificar visualmente se foi aplicado o selador (esmalte e verniz) ou o fundo anticorrosivo (em superfícies metálicas).","[\"Pintura\",\"Tinta Esmalte Verniz :: Reforço na Pintura\"]":"INSTRUÇÃO:\nVerificar visualmente se as arestas, cantos, fendas, rebites, cabeças de parafusos e cordões de solda receberam reforço de pintura.","[\"Pintura\",\"Tinta Esmalte Verniz :: Aspecto Final\"]":"INSTRUÇÃO:\nVerificar visualmente se a pintura está uniforme, sem falhas e escorrimentos.","[\"Impermeabilização\",\"Impermeabilização Interna :: Condições de Início dos Serviços\"]":"INSTRUÇÃO:\nAntes de começar os serviços, verificar visualmente se os ralos estão chumbados e o piso está regularizado, e se a 1ª fiada de alvenaria foi executada na área a ser impermeabilizada para posterior recebimento dos shafts. Verificar também a limpeza da base.","[\"Impermeabilização\",\"Impermeabilização Interna :: Reforços nos Ralos e Aplicação do Produto\"]":"INSTRUÇÃO:\nVerificar visualmente se os ralos possuem tela de reforço na execução do serviço. Conferir visualmente se o produto foi aplicado em 3 demãos cruzadas.","[\"Impermeabilização\",\"Impermeabilização Interna :: Falhas na Superfície\"]":"INSTRUÇÃO:\nVerificar visualmente, após a aplicação da impermeabilização e antes da proteção, se a aplicação atingiu toda a superfície do ambiente, virando o rodapé (arredondado) com 40 cm, e se há falhas. Checar se dentro dos ralos foi aplicado o produto corretamente. Verificar se os tubos (passantes) possuem pelo menos 5 cm de impermeabilização. Analisar se há caimento de 0,5% ou conforme projeto nas áreas com ralos.","[\"Impermeabilização\",\"Impermeabilização Interna :: Estanqueidade\"]":"INSTRUÇÃO:\nApós a aplicação da impermeabilização, aplicar uma lâmina de água sobre o local e aguardar por 72 horas.\n\nTOLERÂNCIA:\nNão pode haver vazamento","[\"Impermeabilização\",\"Impermeabilização Interna :: Proteção, Piso Acabado, Contrapiso com Caída e Piso \\\"Oco\\\" Após 7 Dias\"]":"INSTRUÇÃO:\nVerificar o caimento da área molhada e, após 7 dias, se não há piso \"oco\". Analisar se há juntas de retração e trabalho térmico, onde necessário.","[\"Acabamentos\",\"Louças e Metais :: Condição de Início do Serviço\"]":"INSTRUÇÃO:\nVerificar se as louças e metais estão em perfeito estado. Verificar se as instalações de esgoto e água estão funcionando. Verificar se as instalações dos revestimentos e a 1ª demão de pintura estão concluídos. Verificar se a tubulação de esgoto não está obstruída.","[\"Acabamentos\",\"Louças e Metais :: Posição da Tubulação de Esgoto da Bacia\"]":"INSTRUÇÃO:\nVerificar com auxílio de trena a distância do eixo da tubulação de esgoto para a parede do fundo.\n\nTOLERÂNCIA:\nMínimo 32 cm","[\"Acabamentos\",\"Louças e Metais :: Fixação dos Metais e Louças Sanitários\"]":"INSTRUÇÃO:\nMovimentar os metais sanitários e as louças, checando a fixação dos mesmos.","[\"Acabamentos\",\"Louças e Metais :: Teste de Funcionamento e Vazamento\"]":"INSTRUÇÃO:\nApós a ligação de água, abrir os registros, testar o funcionamento das torneiras e louças, e verificar se há vazamentos pelos sifões e vedações.\n\nTOLERÂNCIA:\nNão deve haver vazamentos e o fluxo de água das torneiras deve ser contínuo.","[\"Acabamentos\",\"Louças e Metais :: Aparência do Conjunto Após Instalação: Metais, Louças e Acabamento dos Rejuntes das Louças\"]":"INSTRUÇÃO:\nVisualmente verificar se não há: acabamento opaco, ondulação, bolha, empola, furo, mancha, corpo exposto, pinta, ponta de agulha, risco, amassado, rebarba, corrosão, racho, gretamento, porosidade superficial e irregularidade na moldagem da peça. As peças e elementos não devem possuir cantos vivos e superfícies ásperas.\n\nTOLERÂNCIA:\nNão deve haver nenhum tipo de avaria, as louças e os metais devem estar em perfeito estado.","[\"Acabamentos\",\"Louças e Metais :: Distância Entre Caixa Acoplada e Parede\"]":"INSTRUÇÃO:\nVerificar com auxílio de trena o espaçamento entre a caixa acoplada e a parede.\n\nTOLERÂNCIA:\nDesvio entre 10 mm e 30 mm","[\"Acabamentos\",\"Louças e Metais :: Nivelamento das Louças (Bacia C/ Caixa Acoplada, Lavatório e Tanque)\"]":"INSTRUÇÃO:\nVerificar o nível das peças com auxílio de nível de bolha.\n\nTOLERÂNCIA:\nBolha entre linhas","[\"Acabamentos\",\"Louças e Metais :: Altura do Lavatório e Tanque (Conforme Medidas de Projeto)\"]":"INSTRUÇÃO:\nVerificar com trena de 5 m.\n\nTOLERÂNCIA:\n± 2 cm","[\"Acabamentos\",\"Louças e Metais :: Proteção dos Metais (Torneiras e Misturadores)\"]":"INSTRUÇÃO:\nApós a colocação os mesmos devem ser protegidos utilizando o próprio protetor fornecido pelo fabricante ou plástico com fita adesiva.","[\"Fundação\",\"Sapata Isolada :: Checar a Locação da Sapata\"]":"INSTRUÇÃO:\nAtravés do cruzamento de eixos do gabarito e prumos de eixo.\n\nTOLERÂNCIA:\n± 1 cm","[\"Fundação\",\"Sapata Isolada :: Cota do Fundo da Vala\"]":"INSTRUÇÃO:\nAtravés de um nível de mangueira ou laser, a partir da RN, após a escavação do fundo da vala. Liberação do consultor de fundações junto ao projeto de fundação. Método/procedimento: visual.\n\nTOLERÂNCIA:\n± 5 cm","[\"Fundação\",\"Sapata Isolada :: Forma da Sapata\"]":"INSTRUÇÃO:\nAtravés da trena metálica, verificar as dimensões da caixa. Verificar também o nível e o prumo.\n\nTOLERÂNCIA:\n± 5 mm","[\"Fundação\",\"Sapata Isolada :: Armação da Sapata\"]":"INSTRUÇÃO:\nContar as barras com base no projeto estrutural e verificar se há barra de pararaio.","[\"Fundação\",\"Sapata Isolada :: Gastalho\"]":"INSTRUÇÃO:\nChecagem das dimensões e eixo do gastalho.\n\nTOLERÂNCIA:\n± 3 mm","[\"Fundação\",\"Sapata Isolada :: Arranque do Pilar (ou Vigas Saindo da Sapata)\"]":"INSTRUÇÃO:\nConferir arranques conforme projeto estrutural.\n\nTOLERÂNCIA:\nVisualmente conforme projeto","[\"Fundação\",\"Sapata Isolada :: Concretagem\"]":"INSTRUÇÃO:\nVerificação visual da pirâmide e da cura úmida por 24 hs.","[\"Fundação\",\"Sapata Isolada :: Mapeamento\"]":"INSTRUÇÃO:\nAnotar no próprio projeto de fundações o mapeamento e as excentricidades de cada fundação, para posterior análise do projetista estrutural.","[\"Fundação\",\"Tubulão e Broca :: Condições de Início\"]":"INSTRUÇÃO:\nVerificar se a superfície do terreno está limpa e desimpedida e se a locação dos eixos foi liberada.","[\"Fundação\",\"Tubulão e Broca :: Diâmetro\"]":"INSTRUÇÃO:\nVerificar o diâmetro do fuste em relação ao previsto em projeto (após a escavação do fuste) utilizando-se de trena metálica.\n\nTOLERÂNCIA:\n± 2 cm","[\"Fundação\",\"Tubulão e Broca :: Cota de Apoio\"]":"INSTRUÇÃO:\nVerificar a cota de apoio em relação à definida em projeto e dos resultados da sondagem (antes do alargamento da base).\n\nTOLERÂNCIA:\n± 5 cm","[\"Fundação\",\"Tubulão e Broca :: Dimensões da Base (Apenas para Tubulão)\"]":"INSTRUÇÃO:\nVerificar as dimensões da base em relação as dimensões definidas em projeto (após alargamento).\n\nTOLERÂNCIA:\n± 5 cm","[\"Fundação\",\"Tubulão e Broca :: Checagem da Armadura\"]":"INSTRUÇÃO:\nVerificar a quantidade, o comprimento e a bitola das barras, conforme projeto de fundação.","[\"Fundação\",\"Tubulão e Broca :: Cota de Arrasamento\"]":"INSTRUÇÃO:\nVerificar visualmente 30 min após a concretagem se a cota de arrasamento e da armação não se alteram (desce).","[\"Fundação\",\"Hélice Contínua :: Condições de Início\"]":"INSTRUÇÃO:\nVerificar se a superfície do terreno está limpa e desimpedida. Verificar se as estacas foram locadas no chão do terreno pelo topógrafo conforme projeto. Solicitar a carta traço ao fornecedor de concreto da obra.","[\"Fundação\",\"Hélice Contínua :: Estaca Prova\"]":"INSTRUÇÃO:\nExecutar uma peça em local que não compreenda a área da edificação, uma peça \"prova\", para análise das especificações técnicas e de projeto.","[\"Fundação\",\"Hélice Contínua :: Locação das Estacas\"]":"INSTRUÇÃO:\nVerificar a locação das estacas, com o cruzamento dos arames do gabarito e trena, confirmando o diâmetro das estacas.\n\nTOLERÂNCIA:\n± 3 mm","[\"Fundação\",\"Hélice Contínua :: Prumo do Equipamento\"]":"INSTRUÇÃO:\nVerificar visualmente se a máquina está aprumada.","[\"Fundação\",\"Hélice Contínua :: Cota de Apoio\"]":"INSTRUÇÃO:\nVerificar na máquina a cota de apoio em relação à definida em projeto. Em caso de liberação do consultor, deve-se registrar e arquivar essa informação.\n\nTOLERÂNCIA:\nDefinida em projeto ou liberada pelo consultor","[\"Fundação\",\"Hélice Contínua :: Concreto\"]":"INSTRUÇÃO:\nVerificar traço no projeto de fundação.","[\"Fundação\",\"Hélice Contínua :: Checagem da Armadura Longitudinal\"]":"INSTRUÇÃO:\nVerificar a quantidade, o comprimento e a bitola das barras, conforme projeto de fundação.","[\"Fundação\",\"Hélice Contínua :: Cota de Arrasamento\"]":"INSTRUÇÃO:\nVerificar visualmente 30 minutos após a cravação se a cota de arrasamento e da armação não se altera (desce).","[\"Fundação\",\"Hélice Contínua :: Ensaio de Prova de Carga\"]":"INSTRUÇÃO:\nPara projetos com mais de 100 estacas, deve-se realizar o ensaio conforme previsto na NBR 6122.","[\"Fundação\",\"Hélice Contínua :: Registros da Execução\"]":"INSTRUÇÃO:\nAo término do serviço, solicitar ao executor os registros da execução, contendo: identificação da obra, local, nome do operador, executor e contratante; características do equipamento; identificação da estaca.","[\"Fundação\",\"Estaca Strauss :: Condições de Início\"]":"INSTRUÇÃO:\nVerificar se a superfície do terreno está limpa e desimpedida.","[\"Fundação\",\"Estaca Strauss :: Locação das Estacas\"]":"INSTRUÇÃO:\nVerificar a locação das estacas, com o cruzamento dos arames do gabarito e trena.\n\nTOLERÂNCIA:\n± 3 mm","[\"Fundação\",\"Estaca Strauss :: Prumo do Equipamento\"]":"INSTRUÇÃO:\nVerificar visualmente se o tripé está aprumado.","[\"Fundação\",\"Estaca Strauss :: Cota de Apoio\"]":"INSTRUÇÃO:\nVerificar a cota de apoio em relação à definida em projeto.","[\"Fundação\",\"Estaca Strauss :: Cota de Arrasamento\"]":"INSTRUÇÃO:\nVerificar visualmente 30 minutos após a cravação se a cota de arrasamento e da armação não se altera (desce).","[\"Fundação\",\"Estaca Strauss :: Checagem da Armadura\"]":"INSTRUÇÃO:\nVerificar a quantidade, o comprimento e a bitola das barras, conforme projeto de fundação.","[\"Fundação\",\"Perfil Metálico :: Condições de Início\"]":"INSTRUÇÃO:\nVerificar se a superfície do terreno está limpa e desimpedida, se a locação dos perfis foi liberada e se não há interferências no local da cravação. Verificar o topo do perfil e se a cota de topo está acima do nível do piso do vizinho.","[\"Fundação\",\"Perfil Metálico :: Tipo de Perfil e Comprimento do Mesmo\"]":"INSTRUÇÃO:\nChecar se está de acordo com o projeto de fundação.","[\"Fundação\",\"Perfil Metálico :: Emendas nos Perfis\"]":"INSTRUÇÃO:\nEm caso de emendas, verificar se a execução atende ao projeto.","[\"Fundação\",\"Perfil Metálico :: Cotas\"]":"INSTRUÇÃO:\nVerificar se a cota de topo e a cota de ponta estão de acordo com as definidas em projeto (em solos muito duros, cravar o perfil até dar nega e passar ao consultor a cota de ponta para análise).\n\nTOLERÂNCIA:\n5 cm ou conforme liberação do consultor","[\"Fundação\",\"Perfil Metálico :: Relatório de Execução dos Perfis\"]":"INSTRUÇÃO:\nApós o término do serviço ou etapa, solicitar ao fornecedor o envio do boletim de execução do serviço (e anexar o mesmo nesta FVS para futuro arquivamento).","[\"Fundação\",\"Parede Diafragma :: Condições de Início de Serviço\"]":"INSTRUÇÃO:\nO terreno deve estar limpo e desobstruído.","[\"Fundação\",\"Parede Diafragma :: Dimensões da Mureta Guia\"]":"INSTRUÇÃO:\nConferir a locação da mureta guia realizada pelo topógrafo. Verificar as dimensões da mureta guia, com auxílio de uma trena, antes da concretagem.\n\nTOLERÂNCIA:\n4 cm de folga em relação às medidas da parede diafragma","[\"Fundação\",\"Parede Diafragma :: Prumo e Alinhamento da Mureta Guia\"]":"INSTRUÇÃO:\nVerificar visualmente o prumo e alinhamento da mureta guia, antes da concretagem da parede diafragma.","[\"Fundação\",\"Parede Diafragma :: Armação da Parede Diafragma\"]":"INSTRUÇÃO:\nVerificar se a armação foi executada conforme especificações do projeto de fundação.","[\"Fundação\",\"Parede Diafragma :: Cota da Parede Acabada\"]":"INSTRUÇÃO:\nVerificar com o auxílio de trena e mangueira de nível se após a concretagem a cota da parede acabada está de acordo com o que foi orientado pelo consultor.\n\nTOLERÂNCIA:\nVariação definida e aprovada pelo consultor.","[\"Serviços Preliminares\",\"Escavação :: Condição de Início de Serviço\"]":"INSTRUÇÃO:\nPrimitivo feito pelo topógrafo, definição da cota de escavação (junto ao coordenador e consultor) e execução dos laudos da terra (análise).","[\"Serviços Preliminares\",\"Escavação :: Cota e Nivelamento da Escavação\"]":"INSTRUÇÃO:\nVerificar a cota final e o nivelamento do terreno escavado, com auxílio de mangueira de nível e trena, com base no projeto.","[\"Serviços Preliminares\",\"Escavação :: Inclinação do Talude\"]":"INSTRUÇÃO:\nVerificar visualmente a inclinação do talude, com auxílio de um gabarito e com base no projeto de fundação.","[\"Serviços Preliminares\",\"Escavação :: Largura da Berma\"]":"INSTRUÇÃO:\nVerificar a largura da berma de escavação utilizando trena, com base no projeto de fundação.","[\"Fundação\",\"Compactação de Aterro :: Condição para Início dos Serviços\"]":"INSTRUÇÃO:\nVerificar a limpeza do terreno, antes do início dos serviços.","[\"Fundação\",\"Compactação de Aterro :: Camadas de Compactação\"]":"INSTRUÇÃO:\nVisual, uma vez por dia a qualquer hora, não devendo superar 30 cm de espessura.","[\"Fundação\",\"Compactação de Aterro :: Acabamento Final\"]":"INSTRUÇÃO:\nVisual, após a conclusão dos serviços, inclinação dos taludes, a cota e uniformidade do terreno.","[\"Instalações Elétricas\",\"Condição para Início dos Serviços\"]":"INSTRUÇÃO:\nA alvenaria deve estar concluída.","[\"Instalações Elétricas\",\"Passagem e Diâmetro dos Eletrodutos Embutidos nas Paredes e Caixas Elétricas\"]":"INSTRUÇÃO:\nVisual, antes da fixação e revestimento com argamassa nos rasgos da parede. Caixas de passagem nas AQ com 0,5 cm e nas AF com 1,0 cm para fora da alvenaria.","[\"Instalações Elétricas\",\"Quadros Elétricos\"]":"INSTRUÇÃO:\nVisualmente, após sua fixação e montagem dos circuitos, com disjuntores etc.","[\"Instalações Elétricas\",\"Tomadas, Ponto de TV, Interruptores, Telefone e Interfone\"]":"INSTRUÇÃO:\nVerificar a quantidade e o nível, tendo como referência opções de planta e projeto de furação de alvenaria.","[\"Instalações Elétricas\",\"Tomadas 220v\"]":"INSTRUÇÃO:\nVerificar se as tomadas 220V das unidades e áreas comuns estão devidamente identificadas.","[\"Instalações Elétricas\",\"Prumadas de Cabos ou Busway\"]":"INSTRUÇÃO:\nVerificar visualmente as especificações (bitolas e tubos), fixações e a presença de lã de rocha. O busway deve ter iluminação e ventilação próprias.","[\"Instalações Elétricas\",\"Fiação e Arame Guia\"]":"INSTRUÇÃO:\nVerificar quantidade e bitola dos fios e a passagem de arame guia (TV).","[\"Instalações Elétricas\",\"Proteção de Caixas de Elétrica\"]":"INSTRUÇÃO:\nVerificar o preenchimento das caixas com papel amassado.","[\"Instalações Hidráulicas\",\"Condição para Início dos Serviços\"]":"INSTRUÇÃO:\nAs taliscas deverão estar prontas para os pontos de gás, água e esgoto (parede e piso) – considerar o revestimento cerâmico.","[\"Instalações Hidráulicas\",\"Posicionamento de Ralos\"]":"INSTRUÇÃO:\nVerificar posicionamento de ralos conforme paginação do piso cerâmico.\n\nTOLERÂNCIA:\n± 10 mm","[\"Instalações Hidráulicas\",\"Posicionamento dos Pontos (Consumo de Água, Registros, Válvulas, Sistema de Esgoto e Gás)\"]":"INSTRUÇÃO:\nAtravés de trena metálica, após a conclusão da tubulação.\n\nTOLERÂNCIA:\n± 5 mm","[\"Instalações Hidráulicas\",\"Prumadas\"]":"INSTRUÇÃO:\nVerificar visualmente material, quantidade de tubos, bitolas, prumo e posição.","[\"Instalações Hidráulicas\",\"Chumbamento das Tubulações e Ralos\"]":"INSTRUÇÃO:\nVerificar se as tubulações (shafts) foram chumbadas com cimento e areia 1:6; ralos e pontos de bacia com graute ou similar.","[\"Instalações Hidráulicas\",\"Posicionamento dos Drenos na Marcação da Alvenaria\"]":"INSTRUÇÃO:\nVerificação em projeto, e acompanhamento da equipe de hidráulica, juntamente com a marcação da alvenaria.\n\nTOLERÂNCIA:\n± 5 mm","[\"Instalações Hidráulicas\",\"Posicionamento e Distribuição dos Esgotos (Aranha)\"]":"INSTRUÇÃO:\nVerificar caimento das tubulações até o ralo sifonado, e verificar se todas as conexões foram executadas conforme projeto.","[\"Instalações Hidráulicas\",\"Kits Hidráulicos\"]":"INSTRUÇÃO:\nVerificar se os kits estão conforme projeto, e se os mesmos estão com os registros nivelados.\n\nTOLERÂNCIA:\n± 2 mm","[\"Instalações Hidráulicas\",\"Tubos para Exaustão dos Banhos com Ventilação Forçada\"]":"INSTRUÇÃO:\nVerificar se a bitola e as tubulações do ventokit estão conforme projeto.","[\"Instalações Hidráulicas\",\"Chumbamento de Passantes Fachada\"]":"INSTRUÇÃO:\nVerificar se os passantes da fachada estão com 4 mm de desnível para a fachada, para evitar entrada de água no apartamento.\n\nTOLERÂNCIA:\n± 2 mm","[\"Instalações Hidráulicas\",\"Encamisamento / Ventilação do Gás\"]":"INSTRUÇÃO:\nVerificar se o ramal/prumada de gás foi encamisado ou se foi prevista ventilação conforme exigência da concessionária.","[\"Instalações Hidráulicas\",\"Cavaletes de Água e Redutoras de Pressão\"]":"INSTRUÇÃO:\nVerificar se os cavaletes dos shafts e as redutoras de pressão estão montados conforme o projeto, e se a pressão atende à norma NBR 5626.","[\"Instalações Hidráulicas\",\"Pressurização da Tubulação de Água Fria e Quente\"]":"INSTRUÇÃO:\nPressurizar a tubulação com carga de 1,5 kgf/cm² e verificar ocorrência de vazamentos.","[\"Instalações Hidráulicas\",\"Pressurização da Tubulação de Gás (Antes do Fechamento)\"]":"INSTRUÇÃO:\nPressurizar a tubulação com carga de 2,0 kgf/cm² e verificar ocorrência de vazamentos, antes do fechamento das tubulações.","[\"Instalações Hidráulicas\",\"Pressurização da Tubulação de Gás (Depois da Conclusão dos Revestimentos Cerâmicos)\"]":"INSTRUÇÃO:\nPressurizar a tubulação com carga de 2,0 kgf/cm² e verificar ocorrência de vazamentos, depois da conclusão do revestimento cerâmico.","[\"Instalações Hidráulicas\",\"Funcionamento do Sistema de Esgoto\"]":"INSTRUÇÃO:\nTampar o ponto de encontro do ramal com a prumada e colocar água, verificando a ocorrência de vazamentos.","[\"Instalações Hidráulicas\",\"Funcionamento do Sistema de Combate a Incêndio\"]":"INSTRUÇÃO:\nVerificar visualmente a pressão e o funcionamento do sistema (hidrantes e mangueiras).","[\"Instalações Hidráulicas\",\"Proteção dos Registros\"]":"INSTRUÇÃO:\nApós a colocação, os registros devem ser protegidos utilizando o protetor fornecido pelo fabricante ou plástico com fita adesiva.","[\"Instalações Hidráulicas\",\"Medidor de Água Fria\"]":"INSTRUÇÃO:\nConferir marca e modelo do medidor, e se existem vazamentos após a instalação do mesmo.","[\"Instalações Hidráulicas\",\"Limpeza e Proteção dos Ralos\"]":"INSTRUÇÃO:\nProceder à limpeza das caixas sifonadas, proteger os ralos com espuma ou pedaço de tela plástica e colocar a grelha.","[\"Instalações Hidráulicas\",\"Instalação de Louças (Bacia)\"]":"INSTRUÇÃO:\nVerificar se as bacias estão niveladas, e conferir marca e modelo caso haja personalização.\n\nTOLERÂNCIA:\n± 2 mm","[\"Instalações Hidráulicas\",\"Acabamento de Registros\"]":"INSTRUÇÃO:\nVerificar se os acabamentos de registros estão nivelados, e conferir marca e modelo caso haja personalização.","[\"Instalações Hidráulicas\",\"Metais\"]":"INSTRUÇÃO:\nVerificar se os metais estão instalados conforme marca e modelo, caso haja personalização.","[\"Instalações Hidráulicas\",\"Sifão e Acessórios\"]":"INSTRUÇÃO:\nVerificar possíveis vazamentos após a instalação dos sifões.","[\"Impermeabilização\",\"Impermeabilização com Manta :: Condições de Início dos Serviços\"]":"INSTRUÇÃO:\nVerificar visualmente as condições da base — sem material solto, pontas de aço de armaduras ou rebarbas de concreto. As tubulações devem estar chumbadas. Verificar se existem juntas de dilatação na área a ser impermeabilizada. Vedar o local de execução durante a atividade.","[\"Impermeabilização\",\"Impermeabilização com Manta :: Regularização Acabada\"]":"INSTRUÇÃO:\nDemarcar as floreiras, muros e muretas para definir caimentos antes da execução da regularização acabada.","[\"Impermeabilização\",\"Impermeabilização com Manta :: Pintura da Base\"]":"INSTRUÇÃO:\nVerificar visualmente, durante a aplicação, se o primer está sendo aplicado nos pontos de aderência da manta à base. A base deve estar totalmente seca.","[\"Impermeabilização\",\"Impermeabilização com Manta :: Cola das Emendas\"]":"INSTRUÇÃO:\nVerificar visualmente, durante a aplicação, se as emendas estão com sobreposição correta e se estão aderidas.\n\nTOLERÂNCIA:\nMínimo 10 cm","[\"Impermeabilização\",\"Impermeabilização com Manta :: Cantos e Detalhes\"]":"INSTRUÇÃO:\nVerificar visualmente, durante a aplicação, se a manta sobe pelos rodapés e tubulações emergentes, e se está acima do nível da água e do jardim. Checar se os cantos estão arredondados e se foi aplicada tela plástica ou de galinheiro com a mesma altura da manta no local.\n\nTOLERÂNCIA:\nMínimo 20 cm","[\"Impermeabilização\",\"Impermeabilização com Manta :: Ralos\"]":"INSTRUÇÃO:\nVerificar se a impermeabilização desce para o interior do tubo e se há sobreposição da manta nesses locais. Verificar se os tubos coletores possuem diâmetro nominal mínimo de 100 mm.","[\"Impermeabilização\",\"Impermeabilização com Manta :: Juntas de Dilatação\"]":"INSTRUÇÃO:\nVerificar se há juntas de dilatação no local, respeitando as distâncias máximas de 3 metros em um sentido e 2 metros no sentido perpendicular ao primeiro.","[\"Impermeabilização\",\"Impermeabilização com Manta :: Estanqueidade\"]":"INSTRUÇÃO:\nApós a aplicação da manta, aplicar uma lâmina de água sobre o local, com no mínimo 10 cm de altura, e aguardar por 72 horas.\n\nTOLERÂNCIA:\nNão pode haver vazamento","[\"Impermeabilização\",\"Impermeabilização com Manta :: Proteção Mecânica\"]":"INSTRUÇÃO:\nVerificar a execução da proteção mecânica (composta por argamassa de cimento e areia) onde necessária, e a espessura dessa proteção em função do local. A proteção mecânica deve possuir tela de fios de arame galvanizados ou plásticos nas áreas verticais.","[\"Acabamentos\",\"Lareira e Churrasqueira :: Condição para Início dos Serviços\"]":"INSTRUÇÃO:\nVerificar antes de fechar o duto da churrasqueira se o mesmo está limpo e desobstruído. Verificar foram executados os encunhamentos próximos as vigas, bem como não foram calafetadas as passagens de elétrica próximas ao duto (quando for o caso). Verificar visualmente a limpeza do local.","[\"Acabamentos\",\"Lareira e Churrasqueira :: Bocal do Exaustor\"]":"INSTRUÇÃO:\nVerificar a posição do bocal após a execução do revestimento interno de parede conforme projeto.\n\nTOLERÂNCIA:\n± 5 mm","[\"Acabamentos\",\"Lareira e Churrasqueira :: Posição e Altura\"]":"INSTRUÇÃO:\nVerificar com trena metálica as medidas conforme o projeto e altura do piso.\n\nTOLERÂNCIA:\n± 5 mm","[\"Acabamentos\",\"Lareira e Churrasqueira :: Acabamento\"]":"INSTRUÇÃO:\nVerificar visualmente, após término da execução da massa, se está bem vedada.","[\"Acabamentos\",\"Lareira e Churrasqueira :: Refratário\"]":"INSTRUÇÃO:\nVerificar visualmente o acabamento do refratário.","[\"Fundação\",\"Tirantes :: Condições de Início de Serviço\"]":"INSTRUÇÃO:\nVerificação de interferência das longarinas em lajes e vigas, e investigação dos furos (existência de interferências como baldrames etc.).","[\"Fundação\",\"Tirantes :: Posicionamento dos Tirantes\"]":"INSTRUÇÃO:\nVerificar a locação do tirante de acordo com o projeto, com auxílio de trena e mangueira de nível.","[\"Fundação\",\"Tirantes :: Montagem dos Tirantes (Cordoalhas)\"]":"INSTRUÇÃO:\nChecar a quantidade, comprimento e posicionamento das cordoalhas, de acordo com o projeto de fundação.","[\"Fundação\",\"Tirantes :: Perfuração na Parede\"]":"INSTRUÇÃO:\nVerificar o grau de inclinação do tirante de acordo com o projeto.","[\"Fundação\",\"Tirantes :: Perfuração dos Tirantes\"]":"INSTRUÇÃO:\nVerificar a perfuração em função do projeto e anexar boletins.","[\"Fundação\",\"Tirantes :: Injeção e Protensão\"]":"INSTRUÇÃO:\nVerificar os boletins de injeção da nata de cimento (de preferência CP V-ARI) e de protensão.","[\"Esquadrias\",\"Colocação de Gradil :: Verificar O Prumo da Fachada e Locação\"]":"INSTRUÇÃO:\nAtravés de arame esticado na fachada ou por meio da locação dos eixos do projeto.\n\nTOLERÂNCIA:\n± 5 mm","[\"Esquadrias\",\"Colocação de Gradil :: Verificar Alinhamento do Gradil\"]":"INSTRUÇÃO:\nAtravés de régua de alumínio no topo e na lateral do gradil.\n\nTOLERÂNCIA:\nPeças até 6 m: tolerância zero; peças ≥ 6 m: 2 mm no total","[\"Esquadrias\",\"Colocação de Gradil :: Nivelamento do Gradil\"]":"INSTRUÇÃO:\nApós a conclusão dos serviços, verificar por meio de régua de nível com bolha o nivelamento do gradil.\n\nTOLERÂNCIA:\nBolha entre linhas","[\"Esquadrias\",\"Colocação de Gradil :: Prumo do Gradil\"]":"INSTRUÇÃO:\nVerificar por meio de prumo de face ou régua com nível de bolha o prumo do gradil.\n\nTOLERÂNCIA:\n2 mm para prumo de face; bolha entre linhas para régua","[\"Esquadrias\",\"Colocação de Gradil :: Verificar O Chumbamento / Firmeza (Fixação no Concreto / Alvenaria)\"]":"INSTRUÇÃO:\nVerificar se a peça está bem fixada.","[\"Esquadrias\",\"Colocação de Gradil :: Distâncias e Medidas\"]":"INSTRUÇÃO:\nVerificar com auxílio de trena metálica as medidas e distâncias entre peças, vãos e elementos, conforme projeto.","[\"Esquadrias\",\"Colocação de Gradil :: Pintura ou Proteção de Gradis de Alumínio, Aço e Suas Ligas\"]":"INSTRUÇÃO:\nVerificar visualmente se o gradil possui pintura ou proteção do revestimento, e se não há danos na superfície.","[\"Esquadrias\",\"Colocação de Gradil :: Ensaios\"]":"INSTRUÇÃO:\nVerificar se o gradil (protótipo) atende aos ensaios normativos conforme ABNT NBR 14718: esforço estático horizontal; esforço estático vertical; resistência a impactos.","[\"Revestimento\",\"Piso Intertravado :: Condições para Início dos Serviços\"]":"INSTRUÇÃO:\nVerificar se a paginação, os níveis e caimento estão definidos. Checar também se o ambiente está limpo e desobstruído.","[\"Revestimento\",\"Piso Intertravado :: Relatórios de Ensaio\"]":"INSTRUÇÃO:\nVerificar se o material possui relatório de ensaio conforme NBR 9781.","[\"Revestimento\",\"Piso Intertravado :: Camadas de Compactação (Aterro)\"]":"INSTRUÇÃO:\nVisual, uma vez por dia a qualquer hora, não devendo superar 30 cm de espessura cada camada.","[\"Revestimento\",\"Piso Intertravado :: Preparo da Base\"]":"INSTRUÇÃO:\nVerificar o nivelamento da bica corrida (aterro) e sarrafeamento do pó-de-pedra ou areia respeitando os caimentos definidos.\n\nTOLERÂNCIA:\n± 2 cm","[\"Revestimento\",\"Piso Intertravado :: Esquadro da Marcação\"]":"INSTRUÇÃO:\nVerificar com esquadro metálico ou trena metálica (3 x 4 x 5) o esquadro da marcação da primeira fiada.","[\"Revestimento\",\"Piso Intertravado :: Vãos e Medidas\"]":"INSTRUÇÃO:\nConferir com auxílio de trena metálica os vãos e medidas definidos em projeto, quando houver, para vagas e/ou circulação de pedestres.\n\nTOLERÂNCIA:\n10 mm","[\"Revestimento\",\"Piso Intertravado :: Aspecto Geral\"]":"INSTRUÇÃO:\nVerificar, visualmente, a variação na espessura das juntas, a presença de dentes ou saliências e o aspecto das juntas, e a planeza do revestimento com auxílio de régua metálica. Verificar o nivelamento do piso com uma régua de 3 m. Verificar se o topo das peças está entre 3 mm e 6 mm acima do nível das caixas de visitas, tampas de bueiros e outras interferências.\n\nTOLERÂNCIA:\n3 mm de planicidade. As juntas devem ter entre 2 mm e 5 mm. Nivelamento: 10 mm em 3 m.","[\"Revestimento\",\"Piso Intertravado :: Caimento\"]":"INSTRUÇÃO:\nTestar com água na superfície, após a execução dos serviços, verificando se não há formação de poças.","[\"Revestimento\",\"Piso Intertravado :: Verificação dos Ralos (Quando Sobre Laje)\"]":"INSTRUÇÃO:\nVerificar se os ralos estão protegidos com bidim.","[\"Gesso\",\"Shaft em Drywall :: Condição de Início de Serviço\"]":"INSTRUÇÃO:\nMarcação preenchida (box e área de serviço), taliscas conferidas, prumadas hidráulicas chumbadas. Verificar visualmente se o tipo de placa (ST, RF, RU, cimentícia) atende ao local de aplicação ou especificação do projeto.","[\"Gesso\",\"Shaft em Drywall :: Transpasses e Posicionamento dos Montantes\"]":"INSTRUÇÃO:\nVerificar com auxílio de trena se os transpasses possuem pelo menos 30 cm e estão desencontrados. Verificar se o espaçamento entre montantes é de no máximo 60 cm entre peças, e se os vãos de portas possuem transpasse de 20 cm.","[\"Gesso\",\"Shaft em Drywall :: Prumo\"]":"INSTRUÇÃO:\nAtravés de régua metálica de 1,80 m com nível de bolha acoplado.\n\nTOLERÂNCIA:\nBolha entre linhas","[\"Gesso\",\"Shaft em Drywall :: Planicidade\"]":"INSTRUÇÃO:\nVerificar por meio de régua metálica de 2,0 m de comprimento a planicidade da superfície.\n\nTOLERÂNCIA:\n5 mm","[\"Gesso\",\"Shaft em Drywall :: Esquadro\"]":"INSTRUÇÃO:\nAtravés de esquadro metálico de 60 cm x 80 cm.\n\nTOLERÂNCIA:\n± 3 mm","[\"Gesso\",\"Shaft em Drywall :: Reforço de Madeira\"]":"INSTRUÇÃO:\nVerificar a instalação da chapa de virolinha nos pontos de tanque e bancadas.","[\"Gesso\",\"Shaft em Drywall :: Aspecto Final\"]":"INSTRUÇÃO:\nAntes do fechamento do shaft, verificar a limpeza dentro do shaft, a aplicação e o acabamento da fita e da massa de rejunte. A superfície final das paredes não deve estar contaminada por pó, nem possuir deformações.","[\"Gesso\",\"Paredes em Drywall :: Condição para Início do Serviço\"]":"INSTRUÇÃO:\nO local deve estar limpo. Contrapiso, massa interna ou gesso liso de parede e teto devem estar concluídos. Verificar visualmente se o tipo de placa (ST, RF, RU, cimentícia) atende ao local de aplicação ou especificação do projeto.","[\"Gesso\",\"Paredes em Drywall :: Marcação das Paredes e Vão de Portas\"]":"INSTRUÇÃO:\nConferir medidas de acordo com o projeto.","[\"Gesso\",\"Paredes em Drywall :: Reforço de Madeira\"]":"INSTRUÇÃO:\nVerificar a instalação da chapa virolinha nos pontos de tanque e bancada.","[\"Gesso\",\"Paredes em Drywall :: Esquadro das Paredes\"]":"INSTRUÇÃO:\nAtravés de esquadro metálico de 60 cm x 80 cm.\n\nTOLERÂNCIA:\n± 3 mm","[\"Gesso\",\"Paredes em Drywall :: Prumo das Paredes e Pontos Elétricos Antes do Fechamento\"]":"INSTRUÇÃO:\nConferir prumo e planicidade das paredes com auxílio de uma régua de 1,80 m com bolha, e os pontos elétricos.","[\"Gesso\",\"Paredes em Drywall :: Planicidade\"]":"INSTRUÇÃO:\nVerificar por meio de régua metálica de 2,0 m de comprimento a planicidade da superfície.\n\nTOLERÂNCIA:\n5 mm","[\"Gesso\",\"Paredes em Drywall :: Cantoneira de Canto\"]":"INSTRUÇÃO:\nVerificar se está instalada, caso seja necessário.","[\"Gesso\",\"Paredes em Drywall :: Aspecto Geral\"]":"INSTRUÇÃO:\nAplicação e acabamento da fita e da massa de rejunte. A superfície final das paredes não deve estar contaminada por pó, nem possuir deformações.","[\"Piscina\",\"Condição para Início dos Serviços\"]":"INSTRUÇÃO:\nVerificar visualmente a condição da base — sem material solto, pontas de aço ou rebarbas de concreto. Fazer taliscamento para chumbar os adaptadores. Verificar a altura do banco de transferências ou escada conforme projeto. Verificar o posicionamento dos chumbadores do corrimão da escada e barra de transferência, quando houver. Em caso de equipamento de transferência, verificar se o projeto indica área de aproximação. Impermeabilização concluída.","[\"Piscina\",\"Botão de Emergência\"]":"INSTRUÇÃO:\nVerificar se o botão de emergência foi executado conforme posicionamento e especificações do projeto.","[\"Piscina\",\"Proteção Mecânica\"]":"INSTRUÇÃO:\nVerificar a execução da proteção mecânica onde necessária, e a espessura dessa proteção em função do local, aplicando tela em toda a extensão das paredes, prolongando 50 cm além da borda.","[\"Piscina\",\"Escada\"]":"INSTRUÇÃO:\nExecutar a alvenaria das escadas, fazendo enchimento com cinasita. Posicionar os chumbadores dos corrimãos da escada. Executar manta asfáltica sobre os degraus. Verificar se as medidas estão conforme as especificações do projeto.","[\"Piscina\",\"Contrapiso\"]":"INSTRUÇÃO:\nExecutar taliscas e verificar o caimento para os ralos. Após uma semana, verificar se o som está oco por meio de batidas com cabo de vassoura ou martelo de borracha.","[\"Piscina\",\"Revestimento\"]":"INSTRUÇÃO:\nTaliscar a piscina para não haver corte de pastilha. Visualizar o aspecto final, cantos vivos arredondados, o alinhamento das bordas e verificar a aplicação do tratamento anti eflorescência.","[\"Piscina\",\"Borda\"]":"INSTRUÇÃO:\nVerificar a aplicação da argamassa polimérica na base e a pintura do Sikatop 107 no tardoz das pedras. Verificar o nivelamento entre as peças por meio de nível a laser, a planeza do revestimento com auxílio de régua metálica, a variação na espessura das juntas, a presença de dentes ou saliências e o aspecto do rejunte. Verificar se os cantos estão arredondados.\n\nTOLERÂNCIA:\nJuntas: 2 mm a 4 mm","[\"Piscina\",\"Pastilha\"]":"INSTRUÇÃO:\nApós assentadas e rejuntadas todas as peças, verificar visualmente a uniformidade da espessura das juntas, a planicidade, dentes sobressalentes e o uso de peças arredondadas nos cantos vivos. Aplicar o silicone entre a última pastilha e a borda.","[\"Piscina\",\"Degraus, Corrimãos e Barras de Apoio\"]":"INSTRUÇÃO:\nConferir se esses elementos possuem acabamento arredondado.","[\"Piscina\",\"Profundidade dos Tanques\"]":"INSTRUÇÃO:\nVerificar se a profundidade do tanque infantil é de 0,5 m, e se a distância entre a superfície da água e o topo é de 0,20 m. Para os demais tanques, a distância entre a superfície da água e o topo deve ser de 0,20 m.","[\"Piscina\",\"Marcas Indicadoras\"]":"INSTRUÇÃO:\nVerificar com auxílio de trena metálica se a piscina possui marcas indicadoras de profundidade e mudanças de inclinação. Verificar se há contrastes de cores nos locais mais profundos do tanque, respeitando distância máxima de 5 m.","[\"Piscina\",\"Aspecto Final\"]":"INSTRUÇÃO:\nLavar a piscina e encher após 3 dias do rejuntamento das pastilhas.","[\"Estrutura\",\"Piso Armado :: Condições para Início do Serviço\"]":"INSTRUÇÃO:\nO terreno deve estar nivelado e limpo (sem sobras de madeira, aço, escoramentos e entulho). A cota do piso deve estar marcada nos pilares existentes. As drenagens, caixas de passagem, tubulações hidráulicas e elétricas (SPDA) devem estar conferidas conforme os respectivos projetos. Verificar se haverá alguma intervenção ambiental abaixo do piso armado. Definir a área a ser concretada.","[\"Estrutura\",\"Piso Armado :: Espessura da Camada de Brita\"]":"INSTRUÇÃO:\nVerificar por meio de uma trena, a espessura da camada de brita (5,0 cm).\n\nTOLERÂNCIA:\n± 5 mm","[\"Estrutura\",\"Piso Armado :: Lona Plástica Preta Reforçada\"]":"INSTRUÇÃO:\nVerificar visualmente se a lona está esticada em toda a área do piso – filme impermeável.","[\"Estrutura\",\"Piso Armado :: Isopor\"]":"INSTRUÇÃO:\nVerificar visualmente se o isopor está instalado no perímetro da estrutura e alvenarias.","[\"Estrutura\",\"Piso Armado :: Armadura\"]":"INSTRUÇÃO:\nVerificar se as camadas de espaçador treliçado, tela Q-138, reforços nos pilares e barras de transferência estão de acordo com o detalhamento do projeto.","[\"Estrutura\",\"Piso Armado :: Lançamento do Concreto\"]":"INSTRUÇÃO:\nVerificar o adensamento do concreto durante a concretagem. Conferir na execução se a cota do piso acabado atende o definido em projeto.","[\"Estrutura\",\"Piso Armado :: Cura Química\"]":"INSTRUÇÃO:\nAcompanhar a aplicação da cura química no piso, após a pega do concreto.","[\"Estrutura\",\"Piso Armado :: Juntas Serradas\"]":"INSTRUÇÃO:\nApós o processo de cura química, verificar a marcação e execução dos cortes das juntas serradas (perpendicular a todos os pilares – 50 cm).","[\"Estrutura\",\"Piso Armado :: Dreno nas Cortinas\"]":"INSTRUÇÃO:\nEm toda a extensão da cortina, deve-se deixar o dreno 10 cm antes de atingir a estrutura (verificar com o projetista estrutural).","[\"Estrutura\",\"Piso Armado :: Aplicação do Selante (1,101,0 Cm)\"]":"INSTRUÇÃO:\nVerificar se o selante de silicone foi aplicado acima do isopor no perímetro da estrutura. Profundidade 1,0 cm.","[\"Estrutura\",\"Piso Armado :: Juntas de Dilatação (Juntas de Construção)\"]":"INSTRUÇÃO:\nVerificar o acabamento final após a aplicação da \"junta jeene\" nas juntas de construção.","[\"Alvenaria\",\"Muros Externos :: Condição para Início dos Serviços\"]":"INSTRUÇÃO:\nVerificar visualmente a limpeza do local, transferência de eixos, chapisco e arranques na estrutura.","[\"Alvenaria\",\"Muros Externos :: Posicionamento da Fiada de Marcação\"]":"INSTRUÇÃO:\nAtravés de trena metálica, verificar a posição em relação aos eixos, de acordo com o projeto.","[\"Alvenaria\",\"Muros Externos :: Alinhamento da Fiada de Marcação\"]":"INSTRUÇÃO:\nVerificar através de linha náilon.\n\nTOLERÂNCIA:\n1 a 3 mm","[\"Alvenaria\",\"Muros Externos :: Elevação da Alvenaria\"]":"INSTRUÇÃO:\nMuros sobre lajes devem ser executados em duas etapas: 1º - eleva-se a alvenaria até 1,60 m, no dia seguinte concreta os pilaretes juntamente com a fiada de canaleta. 2º - elevação restante e no dia seguinte concreta os pilares juntamente com a última fiada que deve ser de canaleta.","[\"Alvenaria\",\"Muros Externos :: Pilares e Pilaretes\"]":"INSTRUÇÃO:\nOs arranques dos pilaretes devem ser deixados durante a execução da estrutura a cada 3 m de comprimento. A cada 3 metros uma dilatação no muro feita por 02 cabeças de bloco de 14 ou 19 cm com bitola mínima de 10 mm grauteado.","[\"Alvenaria\",\"Muros Externos :: Juntas para Muros e Muretas\"]":"INSTRUÇÃO:\nA junta de dilatação a cada 3 m de comprimento deverá ser preenchida com material flexível.","[\"Alvenaria\",\"Muros Externos :: Prumo\"]":"INSTRUÇÃO:\nAtravés de régua metálica de 1,80 m com nível de bolha acoplado.\n\nTOLERÂNCIA:\nBolha entre linhas","[\"Alvenaria\",\"Muros Externos :: Planeza\"]":"INSTRUÇÃO:\nAtravés de trena metálica e régua metálica de 1,80 m com nível e bolha acoplado.\n\nTOLERÂNCIA:\n± 4 mm","[\"Alvenaria\",\"Muros Externos :: Canaletas\"]":"INSTRUÇÃO:\nNas duas canaletas (a do meio e na última) devem ter 2 barras de aço Ø 10 mm - CA-50.","[\"Alvenaria\",\"Muros Externos :: Aspecto Geral da Alvenaria\"]":"INSTRUÇÃO:\nVisualmente, verificando rebarbas, nivelamento, uniformidade e preenchimento das juntas ou blocos quebrados.","[\"Paisagismo\",\"Condições para Início dos Serviços\"]":"INSTRUÇÃO:\nPreparar o solo para receber as espécies e observar se existe a presença de algum objeto que dificulte o plantio.","[\"Paisagismo\",\"Quantitativo\"]":"INSTRUÇÃO:\nConferir as quantidades de cada espécie (árvores e mudas) conforme projetos de paisagismo e projeto aprovado.","[\"Paisagismo\",\"Posicionamento\"]":"INSTRUÇÃO:\nConferir posicionamento de cada espécie conforme projetos de paisagismo e projeto aprovado.","[\"Paisagismo\",\"Vistoria Depave\"]":"INSTRUÇÃO:\nApós o plantio, é fundamental realizar o acompanhamento constante para garantir a preservação das espécies, evitando seu desaparecimento até a data da vistoria realizada pelo DEPAVE para a emissão do CRP (Certificado de Recebimento Provisório)."};
